function computeMobileFloatingBarOpacity(scrollTop: number): number {
  return scrollTop <= MOBILE_FLOATING_BAR_THRESHOLD
    ? 1
    : Math.max(0, 1 - (scrollTop - MOBILE_FLOATING_BAR_THRESHOLD) / MOBILE_FLOATING_BAR_FADE_RANGE);
}

