const GENESIS_FUEL_PACK_LS_PREFIX = 'beamio:biz:eoa:'
const GENESIS_FUEL_PACK_LS_SUFFIX = ':genesis-fuel-pack-purchased:v1'

function genesisFuelPackPurchasedStorageKey(eoa: string): string {
  return `${GENESIS_FUEL_PACK_LS_PREFIX}${eoa.trim().toLowerCase()}${GENESIS_FUEL_PACK_LS_SUFFIX}`
}

function hasPurchasedGenesisFuelPack(eoa: string | null | undefined): boolean {
  if (!eoa || typeof window === 'undefined') return false
  try {
    return window.localStorage.getItem(genesisFuelPackPurchasedStorageKey(eoa)) === '1'
  } catch {
    return false
  }
}

function markGenesisFuelPackPurchased(eoa: string | null | undefined): void {
  if (!eoa || typeof window === 'undefined') return
  try {
    window.localStorage.setItem(genesisFuelPackPurchasedStorageKey(eoa), '1')
  } catch {
    /* ignore quota */
  }
}

/**
 * Hide Newcomer Genesis when:
 * - local EOA already bought that pack, or
 * - merchant already owns a program card, or
 * - merchant holds Ket #0 (create-card NFT via purchase or redeem).
 */
function visibleMarketFuelPackages(
  eoa: string | null | undefined,
  opts?: { hasMerchantCardOrCreateNft?: boolean },
): MarketFuelPackage[] {
  const hideGenesis =
    hasPurchasedGenesisFuelPack(eoa) || Boolean(opts?.hasMerchantCardOrCreateNft)
  return MARKET_FUEL_PACKAGES.filter((pkg) => !(pkg.firstTimeOnly && hideGenesis))
}

function formatMarketFuelBUnits(pkg: MarketFuelPackage): string {
  return `${pkg.bUnits.toLocaleString('en-US')} B-Units`
}

function formatMarketFuelPriceUsdc(pkg: MarketFuelPackage): string {
  return `$${pkg.priceUsdc.toLocaleString('en-US')}`
}

function formatMarketFuelPoolBreakdown(pkg: MarketFuelPackage): string {
  const bonusPct =
    pkg.bonusBps >= 1000
      ? `${Math.round(pkg.bonusBps / 100)}%`
      : `${(pkg.bonusBps / 100).toFixed(pkg.bonusBps % 100 === 0 ? 0 : 1)}%`
  if (pkg.firstTimeOnly) {
    return `${pkg.paidBUnits.toLocaleString('en-US')} Paid + ${pkg.freeBUnits.toLocaleString('en-US')} Free · ~${bonusPct} subsidy`
  }
  return `${pkg.paidBUnits.toLocaleString('en-US')} Paid + ${pkg.freeBUnits.toLocaleString('en-US')} Free · ${bonusPct} bonus`
}

function formatMarketFuelOrdersHint(pkg: MarketFuelPackage): string {
  const orders = Math.floor(pkg.bUnits / 2)
  return `Supports ~${orders.toLocaleString('en-US')} orders`
}

/** Market / Start Kit shared voucher redeem panel (BusinessStartKet redeem codes). */
function MarketHaveAVoucherPanel(props: {
  redeemInput: string
  onRedeemInputChange: (value: string) => void
  onActivate: () => void
  busy: boolean
  feedback: { type: 'success' | 'error'; message: string } | null
  /** `stacked` = full-width Start Kit fuel list item; `market` = dashed Market band. */
  variant?: 'market' | 'stacked'
}) {
  const { redeemInput, onRedeemInputChange, onActivate, busy, feedback, variant = 'market' } = props
  const stacked = variant === 'stacked'
  return (
    <section
      className={
        stacked
          ? 'rounded-[2rem] border-2 border-dashed border-[#abadaf]/40 bg-[#e5e9eb] p-8 text-center shadow-[0_10px_30px_rgba(0,0,0,0.02)]'
          : 'rounded-xl border-2 border-dashed border-[#abadaf]/30 bg-[#e5e9eb] p-8 text-center'
      }
    >
      <h4 className={`mb-2 font-bold text-[#2c2f31] ${stacked ? 'font-manrope text-xl' : 'text-lg'}`}>
        Have a Voucher?
      </h4>
      <p className={`mx-auto mb-6 max-w-sm text-[#595c5e] ${stacked ? 'text-sm leading-relaxed' : 'text-sm'}`}>
        Enter your expansion code below to instantly credit your business account.
      </p>
      <div className="mx-auto flex max-w-md flex-col gap-2 sm:flex-row">
        <input
          className="flex-1 rounded-full border-none bg-white px-6 py-3 text-center font-mono text-sm tracking-widest text-[#2c2f31] placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-[#0051d1]/20"
          placeholder="ENTER YOUR CODE"
          type="text"
          value={redeemInput}
          onChange={(e) => onRedeemInputChange(e.target.value)}
          autoComplete="off"
          enterKeyHint="done"
          onKeyDown={(e) => {
            if (e.key === 'Enter' && redeemInput.trim() && !busy) {
              e.preventDefault()
              onActivate()
            }
          }}
        />
        <button
          type="button"
          disabled={busy || !redeemInput.trim()}
          onClick={onActivate}
          className="rounded-full bg-[#2c2f31] px-6 py-3 text-sm font-bold text-white transition-colors hover:bg-black disabled:cursor-not-allowed disabled:opacity-50"
        >
          {busy ? '…' : 'Activate'}
        </button>
      </div>
      {feedback ? (
        <p
          className={`mt-4 text-xs font-medium ${
            feedback.type === 'success' ? 'text-emerald-700' : 'text-amber-700'
          }`}
        >
          {feedback.message}
        </p>
      ) : null}
    </section>
  )
}

