/** Directory helpers — `newOnloading.html` Member Directory card row */
function formatDirectoryMemberDisplayName(beamioTag: string): string {
  const t = beamioTag.replace(/^@/, '').trim();
  if (!t) return 'Member';
  return t
    .split(/[_\s.]+/)
    .filter(Boolean)
    .map((w) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase())
    .join(' ');
}

function directoryMemberPointsHuman(row: BizTopupMemberTableRow): number {
  try {
    return Number(BigInt(row.totalTopupFiat6 || '0')) / 1_000_000;
  } catch {
    return 0;
  }
}

function directoryMemberBalancePrefix(currencyRaw: string | undefined): string {
  const currency = (currencyRaw ?? '').trim().toUpperCase();
  if (currency === 'CAD') return 'C$';
  if (currency === 'USD' || currency === 'USDC') return '$';
  if (currency) return `${currency} `;
  return '';
}

function directoryMemberCurrentBalanceDisplay(row: BizTopupMemberTableRow): string {
  const bal = row.currentCardToken0Balance;
  const prefix = directoryMemberBalancePrefix(row.currency);
  if (bal == null || !Number.isFinite(bal)) return `${prefix}—`;
  return `${prefix}${bal.toFixed(2)}`;
}

/** Cumulative top-up points from server `topupPointsTotalE6` (same basis as Top Spender ranking / tier). */
function directoryMemberLifetimeTopupDisplay(row: BizTopupMemberTableRow): string {
  const pts = directoryMemberPointsHuman(row);
  const prefix = directoryMemberBalancePrefix(row.currency);
  return `${prefix}${pts.toFixed(2)}`;
}

function memberDirectoryUserTypeCacheKey(eoaLower: string, viewerNormLower: string): string {
  return `eoa:${eoaLower}:biz:member-user-type-db:v1:${viewerNormLower}`
}

/** Legacy NFC auto-tags: `verra_<n>`. */
const LEDGER_NFC_LEGACY_VERRA_BEAMIO_TAG_RE = /^verra_\d+/i
/** Current NFC auto-tags: `beamio_nfc_<n>`. */
const LEDGER_NFC_BEAMIO_NFC_BEAMIO_TAG_RE = /^beamio_nfc_\d+/i

/** Ledger / Members directory: treat legacy `verra_*` and new `beamio_nfc_*` handles as NFC (not App). */
function isLedgerNfcBeamioTagHandle(handle: string): boolean {
  const h = handle.trim()
  if (!h) return false
  return LEDGER_NFC_LEGACY_VERRA_BEAMIO_TAG_RE.test(h) || LEDGER_NFC_BEAMIO_NFC_BEAMIO_TAG_RE.test(h)
}

function inferMemberDirectoryUserTypeFromBeamioTag(beamioTag: string | null | undefined): MemberDirectoryUserType {
  const handle = (beamioTag ?? '').replace(/^@/, '').trim()
  if (!handle) return 'unknown'
  if (isLedgerNfcBeamioTagHandle(handle)) return 'nfc'
  return 'app'
}

/** When tag / flags are missing, server `firstTopupSource` still distinguishes channels (e.g. `androidNfcTopup`). */
function inferMemberDirectoryUserTypeFromFirstTopupSource(source: string | null | undefined): MemberDirectoryUserType {
  const s = (source ?? '').trim().toLowerCase()
  if (!s) return 'unknown'
  if (s.includes('nfc')) return 'nfc'
  if (s.includes('app') || s.includes('silent') || s.includes('web') || s.includes('browser')) return 'app'
  return 'unknown'
}

function mergeMemberDirectoryUserTypes(a: MemberDirectoryUserType, b: MemberDirectoryUserType): MemberDirectoryUserType {
  if (b !== 'unknown') return b
  if (a !== 'unknown') return a
  return 'unknown'
}

function resolveMemberDirectoryUserType(
  row: BizTopupMemberTableRow,
  db: Record<string, MemberDirectoryUserType>
): MemberDirectoryUserType {
  const direct = inferMemberDirectoryUserTypeFromBeamioTag(row.beamioTag)
  if (direct !== 'unknown') return direct
  const memberLower = row.memberAddress && ethers.isAddress(row.memberAddress) ? ethers.getAddress(row.memberAddress).toLowerCase() : ''
  const aaLower = row.aaAddress && ethers.isAddress(row.aaAddress) ? ethers.getAddress(row.aaAddress).toLowerCase() : ''
  const rawCached = (memberLower && db[memberLower]) || (aaLower && db[aaLower])
  if (rawCached === 'app' || rawCached === 'nfc' || rawCached === 'both') return rawCached
  /** `/api/cardMemberTopups` directory rows often ship before `beamioTag` is hydrated; channel flags still classify App vs NFC. */
  const n = row.usedNfcTopup === true
  const a = row.usedAppTopup === true
  if (n && a) return 'both'
  if (n) return 'nfc'
  if (a) return 'app'
  const fromSource = inferMemberDirectoryUserTypeFromFirstTopupSource(row.firstTopupSource)
  if (fromSource !== 'unknown') return fromSource
  /** Stale localStorage rows may omit flags/source; any directory row with volume is still a member — default App for segment UI. */
  try {
    if (BigInt(row.totalTopupFiat6 || '0') > 0n) return 'app'
  } catch {
    /* ignore */
  }
  if ((row.topupCount ?? 0) > 0) return 'app'
  return 'unknown'
}

function memberDirectoryUserTypeMatchesSegment(type: MemberDirectoryUserType, segment: MembersDirectorySegment): boolean {
  if (segment === 'app') return type === 'app' || type === 'both'
  return type === 'nfc' || type === 'both'
}

/** All-programs + mobile directory: include App, NFC, both, and unknown rows that still have top-up volume (matches merged daemon semantics). */
function filterDirectoryRowsByInclusiveChannel(
  rows: BizTopupMemberTableRow[],
  db: Record<string, MemberDirectoryUserType>,
): BizTopupMemberTableRow[] {
  return rows.filter((r) => {
    const type = resolveMemberDirectoryUserType(r, db)
    if (type === 'app' || type === 'nfc' || type === 'both') return true
    if (type !== 'unknown') return false
    try {
      if (BigInt(r.totalTopupFiat6 || '0') > 0n) return true
    } catch {
      /* ignore */
    }
    return (r.topupCount ?? 0) > 0
  })
}

function formatMemberDirectoryUserTypeLabel(type: MemberDirectoryUserType): string {
  if (type === 'nfc') return 'NFC'
  if (type === 'app') return 'App'
  return '—'
}

function directoryMemberTierFromPoints(points: number): { label: 'Gold' | 'Silver'; gold: boolean } {
  if (points >= 200) return { label: 'Gold', gold: true };
  return { label: 'Silver', gold: false };
}

type MembersRewardTierInfo = {
  highestThreshold: number
  highestLabel: string
}

type MembersRewardTierLevel = {
  threshold: number
  label: string
}

function resolveMembersRewardTierLevels(tiers: CardTierMetadata[] | undefined): MembersRewardTierLevel[] {
  const parsed = (tiers ?? [])
    .map((tier, idx) => {
      const raw = tier.minUsdc6 != null && tier.minUsdc6 !== '' ? Number(tier.minUsdc6) : NaN;
      return {
        threshold: Number.isFinite(raw) ? Math.round(raw / 1_000_000) : NaN,
        label: (tier.name ?? '').trim() || `Tier ${idx + 1}`,
      };
    })
    .filter((tier) => Number.isFinite(tier.threshold) && tier.threshold > 0);
  if (parsed.length < 2) return [];
  const baseThreshold = Math.min(...parsed.map((tier) => tier.threshold));
  return parsed
    .filter((tier) => tier.threshold > baseThreshold)
    .sort((a, b) => a.threshold - b.threshold);
}

function resolveMembersRewardTierBadgeLabelFromLevels(
  levels: MembersRewardTierLevel[] | undefined,
  balance: number | null | undefined
): string | null {
  if (!levels || levels.length === 0) return null;
  if (balance != null && Number.isFinite(balance)) {
    let reached: MembersRewardTierLevel | null = null;
    for (const level of levels) {
      if (balance >= level.threshold) reached = level;
    }
    if (reached) return `${reached.label} Member`;
  }
  return `${levels[0].label} Member`;
}

function resolveMembersRewardTierInfo(tiers: CardTierMetadata[] | undefined): MembersRewardTierInfo | null {
  const parsed = (tiers ?? [])
    .map((tier, idx) => {
      const raw = tier.minUsdc6 != null && tier.minUsdc6 !== '' ? Number(tier.minUsdc6) : NaN;
      return {
        threshold: Number.isFinite(raw) ? Math.round(raw / 1_000_000) : NaN,
        label: (tier.name ?? '').trim() || `Tier ${idx + 1}`,
      };
    })
    .filter((tier) => Number.isFinite(tier.threshold) && tier.threshold > 0);
  if (parsed.length < 3) return null;
  const baseThreshold = Math.min(...parsed.map((tier) => tier.threshold));
  const rewardTiers = parsed.filter((tier) => tier.threshold > baseThreshold);
  if (rewardTiers.length < 2) return null;
  rewardTiers.sort((a, b) => b.threshold - a.threshold);
  const highest = rewardTiers[0];
  return { highestThreshold: highest.threshold, highestLabel: highest.label };
}

function hasMembersRewardTier(tiers: CardTierMetadata[] | undefined): boolean {
  const parsed = (tiers ?? [])
    .map((tier) => {
      const raw = tier.minUsdc6 != null && tier.minUsdc6 !== '' ? Number(tier.minUsdc6) : NaN;
      return Number.isFinite(raw) ? Math.round(raw / 1_000_000) : NaN;
    })
    .filter((v) => Number.isFinite(v) && v > 0);
  if (parsed.length < 2) return false;
  const base = Math.min(...parsed);
  return parsed.some((v) => v > base);
}

function memberRowReachedHighestRewardTier(row: BizTopupMemberTableRow, tierInfo: MembersRewardTierInfo | null): boolean {
  if (!tierInfo) return false;
  const bal = row.currentCardToken0Balance;
  return bal != null && Number.isFinite(bal) && bal >= tierInfo.highestThreshold;
}

type MembersDirectorySegment = 'app' | 'anon_nfc';

