/** BeamioUserCard: `tiers(uint256)` (3 fields) + global `currency` + card-level `upgradeType` */
const USER_CARD_TIERS_AND_CURRENCY_READ_ABI = [
  'function tiers(uint256) view returns (uint256 minUsdc6, uint256 attr, uint256 tierExpirySeconds)',
  'function currency() view returns (uint8)',
  'function upgradeType() view returns (uint8)',
] as const

const USER_CARD_CURRENCY_READ_ABI = ['function currency() view returns (uint8)'] as const

async function fetchBeamioUserCardCurrencyTypeOnly(cardAddress: string, provider: ethers.Provider): Promise<number> {
  const addr = ethers.getAddress(cardAddress)
  const c = new ethers.Contract(addr, USER_CARD_CURRENCY_READ_ABI, provider)
  try {
    const v = Number(await c.currency())
    if (!Number.isFinite(v) || v < 0) return 0
    return v
  } catch {
    return 0
  }
}

type BeamioUserCardChainTier = {
  index: number
  minUsdc6: bigint
  attr: bigint
  tierExpirySeconds: bigint
  upgradeByBalance: boolean
}

async function fetchBeamioUserCardTiersAndCurrencyFromChain(
  cardAddress: string,
  provider: ethers.Provider
): Promise<{ tiers: BeamioUserCardChainTier[]; currencyType: number }> {
  const addr = ethers.getAddress(cardAddress)
  const c = new ethers.Contract(addr, USER_CARD_TIERS_AND_CURRENCY_READ_ABI, provider)
  let upgradeType = 0
  try {
    upgradeType = Number(await c.upgradeType())
  } catch {
    upgradeType = 0
  }
  if (!Number.isFinite(upgradeType) || upgradeType < 0) upgradeType = 0
  const upgradeByBalance = upgradeType === 1
  const rows: BeamioUserCardChainTier[] = []
  for (let i = 0; i < 64; i++) {
    try {
      const r = await c.tiers(i)
      rows.push({
        index: i,
        minUsdc6: BigInt(r[0].toString()),
        attr: BigInt(r[1].toString()),
        tierExpirySeconds: BigInt(r[2].toString()),
        upgradeByBalance,
      })
    } catch {
      break
    }
  }
  rows.sort((a, b) => {
    if (a.minUsdc6 < b.minUsdc6) return -1
    if (a.minUsdc6 > b.minUsdc6) return 1
    return a.index - b.index
  })
  let currencyType = 0
  try {
    currencyType = Number(await c.currency())
  } catch {
    currencyType = 0
  }
  if (!Number.isFinite(currencyType) || currencyType < 0) currencyType = 0
  return { tiers: rows, currencyType }
}

