async function resolveMemberToken0BalanceAccount(
  memberEoa: string,
  directoryAa: string | undefined,
  cardBalanceChainId: number,
  cardBalanceProvider: ethers.Provider,
): Promise<string> {
  if (cardBalanceChainId === CONET_MAINNET_CHAIN_ID) {
    try {
      const resolved = await resolveBeamioAaForEoaWithFallback(cardBalanceProvider, memberEoa);
      if (resolved && ethers.isAddress(resolved)) return ethers.getAddress(resolved);
    } catch {
      /* fall through */
    }
    return ethers.getAddress(memberEoa);
  }
  if (
    directoryAa &&
    ethers.isAddress(directoryAa) &&
    directoryAa.toLowerCase() !== ethers.ZeroAddress.toLowerCase()
  ) {
    return ethers.getAddress(directoryAa);
  }
  return ethers.getAddress(memberEoa);
}

function mapDirectoryApiMembersToBizTopupRows(
  cardAddress: string,
  programName: string,
  currency: string | undefined,
  members: BeamioCardMemberDirectoryPageResponse['members'] | undefined,
): BizTopupMemberTableRow[] {
  const cardLower = ethers.getAddress(cardAddress).toLowerCase();
  const rows: BizTopupMemberTableRow[] = [];
  for (const m of members ?? []) {
    const eoaM = m.memberEoa && ethers.isAddress(m.memberEoa) ? ethers.getAddress(m.memberEoa) : '';
    if (!eoaM) continue;
    const aaRaw = m.memberAa?.trim();
    const aa =
      aaRaw && ethers.isAddress(aaRaw) && aaRaw.toLowerCase() !== ethers.ZeroAddress.toLowerCase()
        ? ethers.getAddress(aaRaw)
        : undefined;
    let lastTs = 0;
    try {
      const t = Date.parse(String(m.lastTopupAt ?? ''));
      if (Number.isFinite(t)) lastTs = Math.floor(t / 1000);
    } catch {
      /* ignore */
    }
    let firstTs = 0;
    const dirM = m as (typeof m) & {
      usedNfc?: boolean;
      usedApp?: boolean;
      firstTopupSource?: string | null;
      firstTopupAt?: string;
    };
    try {
      const ft = Date.parse(String(dirM.firstTopupAt ?? ''));
      if (Number.isFinite(ft)) firstTs = Math.floor(ft / 1000);
    } catch {
      /* ignore */
    }
    rows.push({
      cardLower,
      programName,
      currency,
      memberAddress: eoaM,
      aaAddress: aa,
      topupCount: Number(m.topupCount) || 0,
      totalTopupFiat6: String(m.topupPointsTotalE6 ?? '0'),
      firstSeenTs: firstTs,
      lastSeenTs: lastTs,
      beamioTag: '',
      currentCardToken0Balance: null,
      usedNfcTopup: Boolean(dirM.usedNfc),
      usedAppTopup: Boolean(dirM.usedApp),
      firstTopupSource: dirM.firstTopupSource ?? null,
      firstTopupAtIso: dirM.firstTopupAt ? String(dirM.firstTopupAt) : undefined,
    });
  }
  return rows;
}

/** Active-cards hint when Members daemon rows are empty: 90-day top-up from server `lastTopupAt` only (no per-holder RPC). */
function countRecentActiveMembersFromDirectoryServerOnly(
  members: BeamioCardMemberDirectoryPageResponse['members'] | undefined
): number {
  const since = Math.floor(Date.now() / 1000) - ACTIVE_CARDS_LOOKBACK_DAYS * 24 * 3600;
  let n = 0;
  for (const m of members ?? []) {
    let lastTs = 0;
    try {
      const t = Date.parse(String(m.lastTopupAt ?? ''));
      if (Number.isFinite(t)) lastTs = Math.floor(t / 1000);
    } catch {
      /* ignore */
    }
    if (lastTs > 0 && lastTs >= since) n += 1;
    else if ((Number(m.topupCount) || 0) > 0 && lastTs <= 0) n += 1;
  }
  return n;
}

/**
 * Customer-held points (token #0 display units): on-chain totalSupply minus balances held by the card owner
 * and every admin (EOA + resolved Beamio AA). Charge-style flows redirect points into merchant-side accounts,
 * so this matches "stored value across customer cards" rather than gross issuance (totalSupply alone).
 */
async function fetchCustomerHeldPointsToken0Display(cardAddress: string, provider: ethers.Provider): Promise<number> {
  const card = new ethers.Contract(cardAddress, BEAMIO_USER_CARD_OWNER_ADMIN_LIST_ABI, provider);
  const [supplyRaw, ownerRaw, triple] = await Promise.all([
    card.totalSupply(DASHBOARD_POINTS_TOKEN_ID),
    card.owner(),
    card.getAdminListWithMetadata() as Promise<[string[], string[], string[]]>,
  ]);
  const totalSupply = BigInt(supplyRaw.toString());
  const admins = triple[0] ?? [];
  const merchantEoaLower = new Set<string>();
  const pushEoa = (a: string) => {
    if (!a || !ethers.isAddress(a)) return;
    merchantEoaLower.add(ethers.getAddress(a).toLowerCase());
  };
  pushEoa(ownerRaw as string);
  for (const a of admins) pushEoa(a);

  const accountLower = new Set<string>();
  for (const eoaL of merchantEoaLower) {
    const eoa = ethers.getAddress(eoaL);
    accountLower.add(eoa.toLowerCase());
    try {
      const aa = await resolveBeamioAaForEoaWithFallback(provider, eoa);
      if (aa && ethers.isAddress(aa)) accountLower.add(ethers.getAddress(aa).toLowerCase());
    } catch {
      /* ignore */
    }
  }

  let merchantHeld = 0n;
  for (const low of accountLower) {
    const rawBal = await card.balanceOf(ethers.getAddress(low), DASHBOARD_POINTS_TOKEN_ID);
    merchantHeld += BigInt(rawBal.toString());
  }

  const customerHeld = totalSupply > merchantHeld ? totalSupply - merchantHeld : 0n;
  return amountE6ToDisplayNumber(customerHeld);
}

async function fetchBeamioUserCardToken0BalanceDisplay(
  cardAddress: string,
  account: string,
  provider: ethers.Provider
): Promise<number> {
  const card = new ethers.Contract(cardAddress, BEAMIO_USER_CARD_ERC1155_BALANCE_ABI, provider);
  const raw = await card.balanceOf(ethers.getAddress(account), DASHBOARD_POINTS_TOKEN_ID);
  return amountE6ToDisplayNumber(BigInt(raw.toString()));
}

/** Member directory balances must follow the card's deploy chain (CoNET vs Base). */
function memberHolderToken0BalanceCacheKey(
  partition: string,
  cardLower: string,
  chainId: number,
  holderLower: string
): string {
  return `eoa:${partition}:card:${cardLower}:chain:${chainId}:holder:${holderLower}:balance0:v3`;
}

function compareMembersDirectoryRowsByBalanceThenRecency(
  a: BizTopupMemberTableRow,
  b: BizTopupMemberTableRow,
): number {
  const balA = a.currentCardToken0Balance;
  const balB = b.currentCardToken0Balance;
  const hasA = balA != null && Number.isFinite(balA) && balA > 0;
  const hasB = balB != null && Number.isFinite(balB) && balB > 0;
  if (hasA !== hasB) return hasB ? 1 : -1;
  if (hasA && hasB && balA !== balB) return (balB as number) - (balA as number);
  return (b.lastSeenTs || 0) - (a.lastSeenTs || 0);
}

async function fetchMemberDirectoryHolderBalanceDisplay(
  membersFetchPartition: string,
  cardLower: string,
  cardBalanceChainId: number,
  cardAddress: string,
  balanceAccount: string,
  cardBalanceProvider: ethers.Provider,
): Promise<number | null> {
  const cacheKeyBalance = memberHolderToken0BalanceCacheKey(
    membersFetchPartition,
    cardLower,
    cardBalanceChainId,
    balanceAccount.toLowerCase(),
  );
  return Promise.race<number | null>([
    fetchWithCache(
      cacheKeyBalance,
      () => fetchBeamioUserCardToken0BalanceDisplay(cardAddress, balanceAccount, cardBalanceProvider),
      FETCH_TTL_MS,
      true,
    ),
    rejectMembersBalanceFetchAfter(MEMBERS_BALANCE_FETCH_TIMEOUT_MS),
  ]).catch(() => null as number | null);
}

async function fetchConetBUnitBalanceDisplay(
  account: string,
  provider: ethers.Provider
): Promise<number> {
  const normalized = ethers.getAddress(account);
  try {
    const buintAirdrop = new ethers.Contract(CONET_BUNIT_AIRDROP_ADDRESS, BUNIT_AIRDROP_BALANCE_ABI, provider);
    const raw = await buintAirdrop.getBUnitBalance(normalized);
    return amountE6ToDisplayNumber(BigInt(raw.toString()));
  } catch {
    try {
      const buint = new ethers.Contract(CONET_BUINT, ERC20_BALANCE_ABI, provider);
      const raw = await buint.balanceOf(normalized);
      return amountE6ToDisplayNumber(BigInt(raw.toString()));
    } catch {
      return 0;
    }
  }
}

async function fetchRecentActiveAccountKeysForDashboard(
  cardAddress: string,
  topAdmin: string,
  provider: ethers.Provider,
  lookbackDays: number = ACTIVE_CARDS_LOOKBACK_DAYS
): Promise<string[]> {
  if (!cardAddress || !ethers.isAddress(cardAddress) || !topAdmin || !ethers.isAddress(topAdmin)) return [];
  const indexerAsset = new ethers.Contract(BEAMIO_INDEXER_DIAMOND, INDEXER_ASSET_STATS_ABI, provider);
  const activeAccounts = new Set<string>();
  const pageLimit = 100;
  for (let periodOffset = 0; periodOffset < lookbackDays; periodOffset++) {
    let pageOffset = 0;
    while (true) {
      const [total, , , page] =
        await indexerAsset.getAssetTransactionsByTopAdminAndCurrentPeriodOffsetAndAccountModePaged(
          ethers.getAddress(cardAddress),
          ethers.getAddress(topAdmin),
          PERIOD_DAY,
          periodOffset,
          pageOffset,
          pageLimit,
          TX_CATEGORY_ZERO,
          0,
          CHAIN_ID_FILTER_ALL
        ) as [
          bigint,
          bigint,
          bigint,
          Array<{
            txCategory: string
            payee: string
            payer: string
            exists?: boolean
            displayJson?: string
            subordinate?: string
            topAdmin?: string
          }>,
        ];
      for (const tx of page) {
        if (!tx?.exists) continue;
        const kind = dashboardActivityTypeFromIndexerRow({
          txCategory: String(tx.txCategory),
          payee: tx.payee ?? '',
          displayJson: typeof tx.displayJson === 'string' ? tx.displayJson : undefined,
          payer: tx.payer,
          subordinate: tx.subordinate,
          topAdmin: tx.topAdmin,
        });
        if (kind !== 'Charge' && kind !== 'In-Store Top-Up') continue;
        if (typeof tx.payer === 'string' && ethers.isAddress(tx.payer) && tx.payer !== ethers.ZeroAddress) {
          activeAccounts.add(ethers.getAddress(tx.payer).toLowerCase());
        }
      }
      pageOffset += page.length;
      if (page.length === 0 || page.length < pageLimit || pageOffset >= Number(total)) break;
    }
  }
  return [...activeAccounts];
}

function formatMemberTopupChannelLabel(row: BizTopupMemberTableRow): string {
  const n = row.usedNfcTopup === true;
  const a = row.usedAppTopup === true;
  if (n && a) return 'NFC & App';
  if (n) return 'NFC';
  if (a) return 'App';
  return '—';
}

function formatRegistryApiRowChannel(m: { usedNfc: boolean; usedApp: boolean }): string {
  if (m.usedNfc && m.usedApp) return 'NFC & App';
  if (m.usedNfc) return 'NFC';
  if (m.usedApp) return 'App';
  return '—';
}

const MEMBER_REGISTRY_PAGE_SIZE = 20;

const BEAMIO_CONET_BLOCKSCOUT_ADDRESS_BASE = 'https://scan.conet.network/address' as const;
const BEAMIO_CONET_BLOCKSCOUT_TX_BASE = 'https://scan.conet.network/tx' as const;

function beamioConetBlockscoutAddressUrl(rawAddress: string): string | null {
  try {
    return `${BEAMIO_CONET_BLOCKSCOUT_ADDRESS_BASE}/${ethers.getAddress(rawAddress)}`;
  } catch {
    return null;
  }
}

function beamioConetBlockscoutTxUrl(rawTxHash: string | null | undefined): string | null {
  const h = rawTxHash?.trim();
  if (!h || !/^0x[0-9a-fA-F]{64}$/.test(h)) return null;
  return `${BEAMIO_CONET_BLOCKSCOUT_TX_BASE}/${h}`;
}

function formatConetTxHashShort(rawTxHash: string): string {
  const h = rawTxHash.trim();
  if (h.startsWith('0x') && h.length > 12) return `${h.slice(0, 10)}…${h.slice(-6)}`;
  return h || '—';
}

function ProgramSocialOnChainTxLink({ txHash }: { txHash: string | null }) {
  const href = beamioConetBlockscoutTxUrl(txHash);
  if (!href || !txHash) {
    return (
      <span className="text-[10px] text-[#939699]">{tu('programs_overview_social_tx_unavailable')}</span>
    );
  }
  return (
    <a
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      className={`inline-flex items-center gap-1 rounded-full border border-[#dce2f7] bg-[#e9edff] px-2 py-0.5 font-mono text-[10px] font-medium text-[#0051d1] transition hover:bg-[#dde4ff] ${bizFocusRingClass}`}
      aria-label={tu('programs_overview_social_tx_aria')}
    >
      {formatConetTxHashShort(txHash)}
      <ExternalLink className="h-3 w-3 shrink-0 opacity-80" strokeWidth={2.25} aria-hidden />
    </a>
  );
}

function formatReferrerPoints6Display(raw: string | null | undefined): string {
  if (raw == null || String(raw).trim() === '') return '—';
  try {
    const v = Number(raw) / 1_000_000;
    if (!Number.isFinite(v)) return '—';
    return v.toFixed(2);
  } catch {
    return '—';
  }
}

/** Referrer registry lists login EOAs (API maps chain AA → owner EOA). */
function ProgramReferrerAaCapsule({ address }: { address: string }) {
  return (
    <AddressCapsule
      address={address}
      explorerUrl={beamioConetBlockscoutAddressUrl(address)}
      className="max-w-full border-[#dce2f7] bg-[#e9edff] text-[#424655]"
      leadingIcon={<Wallet className="h-3.5 w-3.5 text-[#0051d1]" strokeWidth={2.25} aria-hidden />}
    />
  );
}

/** 地址胶囊：短缩地址 + 右侧 copy 图标；可选 `explorerUrl` 时点击地址在新标签打开浏览器 */
const AddressCapsule = ({
  address,
  className = '',
  leadingIcon,
  explorerUrl,
}: {
  address: string;
  className?: string;
  leadingIcon?: React.ReactNode;
  explorerUrl?: string | null;
}) => {
  const [copied, setCopied] = useState(false);
  const short = fmtAddr(address);
  const handleCopy = useCallback(async () => {
    if (!address || address.length < 10) return;
    try {
      await navigator.clipboard.writeText(address);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // ignore
    }
  }, [address]);
  const shellClass = `inline-flex items-center gap-2 pl-3 pr-2 py-1.5 rounded-full font-mono text-[11px] font-semibold border transition-colors ${className}`;
  if (explorerUrl) {
    return (
      <div className={shellClass}>
        {leadingIcon ? <span className="shrink-0">{leadingIcon}</span> : null}
        <a
          href={explorerUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="min-w-0 truncate hover:underline"
          aria-label="View contract on CoNET Blockscout (opens in new tab)"
        >
          {short}
        </a>
        <button
          type="button"
          onClick={(e) => {
            e.preventDefault();
            e.stopPropagation();
            void handleCopy();
          }}
          className="shrink-0 opacity-70 transition-opacity hover:opacity-100"
          aria-label="Copy address"
          title="Copy address"
        >
          {copied ? <Check size={12} className="text-emerald-500" /> : <Copy size={12} />}
        </button>
      </div>
    );
  }
  return (
    <button
      type="button"
      onClick={handleCopy}
      className={shellClass}
      title="Copy address"
    >
      {leadingIcon ? <span className="shrink-0">{leadingIcon}</span> : null}
      <span className="truncate">{short}</span>
      {copied ? <Check size={12} className="shrink-0 text-emerald-500" /> : <Copy size={12} className="shrink-0 opacity-70 hover:opacity-100" />}
    </button>
  );
};

/** Smart Receipt drawer — primary card body aligned with desktop Ledger History row (participants, amounts, hash, B-Units, net column). */
function smartReceiptLedgerAmountPreviewColumn(
  tx: TxDisplayRow,
  cadOracle: number,
  pointsCurrencySymbol: string,
): React.ReactNode {
  if (isCreateIssuedNftBuintLedgerRowType(tx.type)) {
    return createIssuedNftBunitAmountPreview(tx);
  }
  if (tx.type === 'Charge') {
    const raw = tx.raw as Record<string, unknown>;
    const meta = parseIndexerMetaTuple(raw.meta);
    const finalFiat = parseIndexerUintE6Field(raw.finalRequestAmountFiat6);
    const pctOffStr = discountRateBpsToPercentOffLabel(meta.discountRateBps);
    if (!(finalFiat > 0)) {
      const finalUsdc = parseIndexerUintE6Field(raw.finalRequestAmountUSDC6);
      if (finalUsdc > 0) {
        return (
          <div className="flex flex-col gap-1.5 items-start">
            <div className="flex items-start gap-2">
              <Coins size={15} className="text-emerald-800 shrink-0 mt-0.5" strokeWidth={2} aria-hidden />
              <div className="flex flex-col min-w-0">
                <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-900 whitespace-nowrap">
                  {finalUsdc.toFixed(2)} <span className="text-[12px] text-slate-400 font-medium">USDC</span>
                </div>
                <span className="text-[11px] text-slate-400 font-medium mt-0.5">
                  ≈ ${(finalUsdc / cadOracle).toFixed(2)} CAD
                </span>
              </div>
            </div>
          </div>
        );
      }
      return <span className="text-[13px] font-medium text-slate-400">—</span>;
    }
    const curLabel = beamioFiatCurrencyLabel(Number(meta.currencyFiat));
    const mainCad = approximateCadFromFinalRequestFiat6(finalFiat, curLabel, cadOracle);
    let tipFiatAdd = 0;
    let tipUsdcAdd = 0;
    if (tx.tipRaw) {
      const tr = tx.tipRaw.raw as Record<string, unknown>;
      tipFiatAdd = parseIndexerUintE6Field(tr.finalRequestAmountFiat6);
      if (!(tipFiatAdd > 0) && tx.tipRaw.usdcAmount > 0) tipUsdcAdd = tx.tipRaw.usdcAmount;
    }
    let embeddedTipHuman = 0;
    if (!tx.tipRaw) {
      const emb = parseChargeBreakdownEmbeddedTip(raw);
      if (emb) {
        const req = emb.requestCurrencyUpper;
        if (req === 'CAD' && curLabel === 'CAD') embeddedTipHuman = emb.tipHuman;
        else if (
          (req === 'USD' || req === 'USDC') &&
          (curLabel === 'USD' || curLabel === 'USDC')
        ) {
          embeddedTipHuman = emb.tipHuman;
        }
      }
    }
    const tipUsdcAsDisplayFiat =
      tipUsdcAdd > 0
        ? curLabel === 'CAD'
          ? tipUsdcAdd / cadOracle
          : curLabel === 'USD' || curLabel === 'USDC'
            ? tipUsdcAdd
            : tipUsdcAdd / cadOracle
        : 0;
    const displayFiatFull = finalFiat + tipFiatAdd + tipUsdcAsDisplayFiat + embeddedTipHuman;
    const cadApproxFull = mainCad + chargeTxDisplayRowMergedTipCad(tx, cadOracle);
    return (
      <div className="flex flex-col gap-1.5 items-start">
        <div className="flex items-start gap-2">
          <Ticket size={15} className="text-emerald-500 shrink-0 mt-0.5" />
          <div className="flex flex-col min-w-0">
            <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-900 whitespace-nowrap">
              {displayFiatFull.toFixed(2)} <span className="text-[12px] text-slate-400 font-medium">{pointsCurrencySymbol}</span>
            </div>
            <span className="text-[11px] text-slate-400 font-medium mt-0.5">≈ ${cadApproxFull.toFixed(2)} CAD</span>
          </div>
        </div>
        {pctOffStr ? (
          <div className="w-fit rounded-lg border border-emerald-200 bg-emerald-50/90 px-2.5 py-1">
            <span className="text-[11px] font-bold text-emerald-800">Auto-Routing: {pctOffStr}% Off</span>
          </div>
        ) : null}
      </div>
    );
  }
  if (tx.type === 'In-Store Top-Up') {
    const meta = parseIndexerMetaTuple(tx.raw.meta);
    const reqFiat = tx.topupBonusFiat && tx.topupBonusFiat > 0
      ? tx.total
      : parseIndexerUintE6Field(meta.requestAmountFiat6);
    return (
      <div className="flex items-start gap-2">
        <Ticket size={15} className="text-emerald-500 shrink-0 mt-0.5" />
        <div className="flex flex-col min-w-0">
          <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-900 whitespace-nowrap">
            {reqFiat.toFixed(2)} <span className="text-[12px] text-slate-400 font-medium">{pointsCurrencySymbol}</span>
          </div>
          <span className="text-[11px] text-slate-400 font-medium mt-0.5">≈ ${reqFiat.toFixed(2)} CAD</span>
          {tx.topupBonusFiat && tx.topupBonusFiat > 0 ? (
            <span className="mt-0.5 inline-flex items-center gap-1 text-[11px] font-bold text-[#FF9500]">
              <span>含</span>
              <span className="inline-flex h-4 w-4 items-center justify-center rounded-full bg-[#FF9500]/15 text-[#FF9500]">
                <Gift size={10} strokeWidth={2.5} />
              </span>
              <span>{formatTopupBonusSubtitleAmount(tx.topupBonusFiat, topupTxDisplayRowCurrencyCode(tx))}</span>
            </span>
          ) : null}
        </div>
      </div>
    );
  }
  if (tx.type === 'Tip' || tx.method === 'Tip') {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-rose-600 whitespace-nowrap">
          <Heart size={15} className="text-rose-500 shrink-0" /> {tx.usdcAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">USDC</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">
          ≈ ${(tx.usdcAmount / cadOracle).toFixed(2)} CAD
        </span>
      </div>
    );
  }
  if (tx.method === 'Mixed') {
    return (
      <>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
            <Ticket size={15} className="text-emerald-500 shrink-0" /> {tx.ctreeAmount.toFixed(2)}{' '}
            <span className="text-[12px] text-slate-400 font-medium">$CTree</span>
          </div>
          <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">≈ ${tx.ctreeAmount.toFixed(2)} CAD</span>
        </div>
        <div className="flex flex-col">
          <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
            <Coins size={15} className="text-emerald-800 shrink-0" /> {tx.usdcAmount.toFixed(2)}{' '}
            <span className="text-[12px] text-slate-400 font-medium">USDC</span>
          </div>
          <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">
            ≈ ${(tx.usdcAmount / cadOracle).toFixed(2)} CAD
          </span>
        </div>
      </>
    );
  }
  if (tx.method === 'Issued $CTree') {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
          <Ticket size={15} className="text-emerald-500 shrink-0" /> {tx.ctreeAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">$CTree</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">≈ ${tx.ctreeAmount.toFixed(2)} CAD</span>
      </div>
    );
  }
  if (tx.method.includes('No Discount')) {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
          <Coins size={15} className="text-emerald-800 shrink-0" /> {tx.usdcAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">USDC</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">
          ≈ ${(tx.usdcAmount / cadOracle).toFixed(2)} CAD
        </span>
      </div>
    );
  }
  if (tx.method.includes('Black Tier')) {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
          <Crown size={15} className="text-yellow-500 shrink-0" /> {tx.ctreeAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">$CTree</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">≈ ${tx.ctreeAmount.toFixed(2)} CAD</span>
      </div>
    );
  }
  if (tx.method === '$CTree or USDC') {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
          <Coins size={15} className="text-emerald-800 shrink-0" /> {tx.usdcAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">USDC</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">
          ≈ ${(tx.usdcAmount / cadOracle).toFixed(2)} CAD
        </span>
      </div>
    );
  }
  if (tx.type === 'B-Unit Fee' || tx.method === 'B-Unit') {
    return createIssuedNftBunitAmountPreview(tx);
  }
  if (tx.ctreeAmount > 0) {
    return (
      <div className="flex flex-col">
        <div className="flex items-center gap-2 text-[14px] font-semibold text-slate-700 whitespace-nowrap">
          <Ticket size={15} className="text-[#34C759] shrink-0" /> {tx.ctreeAmount.toFixed(2)}{' '}
          <span className="text-[12px] text-slate-400 font-medium">$CTree</span>
        </div>
        <span className="text-[11px] text-slate-400 font-medium mt-0.5 ml-6">≈ ${tx.ctreeAmount.toFixed(2)} CAD</span>
      </div>
    );
  }
  return <span className="text-[13px] font-medium text-slate-400">—</span>;
}

type SmartReceiptLedgerAlignedPrimaryCardArgs = {
  tx: TxDisplayRow;
  cadOracle: number;
  pointsCurrencySymbol: string;
  payerAddr: string;
  payerTag: string;
  payeeAddr: string;
  payeeTag: string;
  tierCap: { name: string; backgroundColor?: string } | null | undefined;
  totalCad: number;
  ledgerTypeTitleSr: string;
  ledgerCardStatusSr: { label: string; cls: string };
  isVaultTerminalSr: boolean;
  chargeTxNetValueColumnShowBreakdown: (t: TxDisplayRow) => boolean;
  chargeMetaRequestAmountApproxCad: (t: TxDisplayRow) => number;
  resolveReportingBeamioTag: (addressLower: string) => string;
};

