type ProgramsCouponShareImageStatus = 'idle' | 'loading' | 'success' | 'error';

function sanitizeProgramsCouponShareFilenamePart(raw: string): string {
  const cleaned = raw
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return cleaned || 'beamio-coupon';
}

function programsCouponShareImageFilename(coupon: CardIssuanceCouponRow, shareKind: 'open_claim' | 'redeem'): string {
  const kind = shareKind === 'redeem' ? 'redeem' : 'open-claim';
  return `${sanitizeProgramsCouponShareFilenamePart(coupon.name || coupon.id)}-${kind}.png`;
}

function programsCatalogShareImageFilename(
  production: CardIssuanceProductionRow,
  shareKind: 'open_claim' | 'redeem' = 'open_claim'
): string {
  const kind = shareKind === 'redeem' ? 'redeem' : 'open-claim';
  return `${sanitizeProgramsCouponShareFilenamePart(production.name || production.id)}-catalog-${kind}.png`;
}

function downloadProgramsCouponShareBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1_000);
}

async function captureProgramsCouponSharePng(element: HTMLElement, filename: string): Promise<void> {
  const fontsReady = (document as unknown as { fonts?: { ready?: Promise<unknown> } }).fonts?.ready;
  if (fontsReady) await fontsReady.catch(() => undefined);

  const canvas = await html2canvas(element, {
    backgroundColor: '#ffffff',
    useCORS: true,
    allowTaint: false,
    logging: false,
    scale: Math.min(3, Math.max(2, window.devicePixelRatio || 2)),
  });
  const blob = await new Promise<Blob>((resolve, reject) => {
    canvas.toBlob((result) => {
      if (result) resolve(result);
      else reject(new Error('Unable to render coupon share image.'));
    }, 'image/png');
  });
  downloadProgramsCouponShareBlob(blob, filename);
}

/** Keep freshly registered codes Available until chain confirms active or grace expires. */
const CARD_ISSUANCE_COUPON_REDEEM_CHAIN_CONFIRM_GRACE_MS = 3 * 60_000;

function resolveProgramsCouponRedeemDisplayStatus(args: {
  chainStatus: 'pending' | 'redeemed' | 'cancelled' | 'not_found';
  prevStatus: 'pending' | 'redeemed' | undefined;
  row: CardIssuanceCouponRedeemItemView | undefined;
  chainActiveConfirmed: boolean;
}): { display: 'pending' | 'redeemed'; recordRedeemedAt: boolean } {
  const { chainStatus, prevStatus, row, chainActiveConfirmed } = args;
  if (chainStatus === 'pending') {
    return { display: 'pending', recordRedeemedAt: false };
  }
  if (row?.redeemedAt) {
    return { display: 'redeemed', recordRedeemedAt: false };
  }
  // Chain inactive (consumed / cancelled / not yet indexed). Require prior on-chain active confirmation.
  if (chainActiveConfirmed) {
    return {
      display: 'redeemed',
      recordRedeemedAt: prevStatus === 'pending',
    };
  }
  const createdAt = row?.createdAt ?? 0;
  const recentlyRegistered =
    createdAt > 0 && Date.now() - createdAt < CARD_ISSUANCE_COUPON_REDEEM_CHAIN_CONFIRM_GRACE_MS;
  if (recentlyRegistered) {
    return { display: 'pending', recordRedeemedAt: false };
  }
  // Inactive on chain but never confirmed active: registration failed, cancelled, or not indexed — not consumed.
  return { display: 'pending', recordRedeemedAt: false };
}

/** Remove local redeem rows that never became active on chain (past registration grace). */
function shouldRemoveLocalRedeemNotOnChain(args: {
  chainStatus: 'pending' | 'redeemed' | 'cancelled' | 'not_found';
  chainActiveConfirmed: boolean;
  row: CardIssuanceCouponRedeemItemView | undefined;
}): boolean {
  const { chainStatus, chainActiveConfirmed, row } = args;
  if (chainStatus === 'pending') return false;
  if (chainActiveConfirmed) return false;
  if (row?.redeemedAt) return false;
  const createdAt = row?.createdAt ?? 0;
  if (
    createdAt > 0 &&
    Date.now() - createdAt < CARD_ISSUANCE_COUPON_REDEEM_CHAIN_CONFIRM_GRACE_MS
  ) {
    return false;
  }
  return chainStatus === 'not_found' || chainStatus === 'cancelled';
}

function countRemovedRedeemHashesByIssuanceScope(hashes: Set<string>): {
  couponById: Map<string, number>;
  productionById: Map<string, number>;
} {
  const couponById = new Map<string, number>();
  const productionById = new Map<string, number>();
  const batches = ((CoNET_Data as { cardRedeems?: CardRedeemBatch[] } | null)?.cardRedeems ??
    []) as CardRedeemBatch[];
  for (const batch of batches) {
    for (const item of batch.items) {
      if (!hashes.has(item.hash)) continue;
      if (batch.couponId?.trim()) {
        const id = batch.couponId.trim();
        couponById.set(id, (couponById.get(id) ?? 0) + 1);
      } else if (batch.productionId?.trim()) {
        const id = batch.productionId.trim();
        productionById.set(id, (productionById.get(id) ?? 0) + 1);
      }
    }
  }
  return { couponById, productionById };
}

/** Share modal: only warn when redeem was active on chain and is now inactive (consumed), or local redeemedAt is set. */
function programsRedeemShareShowsConsumedWarning(args: {
  hash: string;
  displayStatus: 'pending' | 'redeemed' | undefined;
  row: CardIssuanceCouponRedeemItemView | undefined;
  chainActiveConfirmed: boolean;
}): boolean {
  const { hash, displayStatus, row, chainActiveConfirmed } = args;
  if (!hash || displayStatus !== 'redeemed') return false;
  if (row?.redeemedAt) return true;
  return chainActiveConfirmed;
}

function collectCouponRedeemRowsByCouponId(
  cardAddress: string | undefined,
  coupons: CardIssuanceCouponRow[]
): Map<string, CardIssuanceCouponRedeemItemView[]> {
  const map = new Map<string, CardIssuanceCouponRedeemItemView[]>();
  const addr = cardAddress?.trim().toLowerCase();
  if (!addr) return map;
  const batches = ((CoNET_Data as { cardRedeems?: CardRedeemBatch[] } | null)?.cardRedeems ??
    []) as CardRedeemBatch[];
  const redeemCoupons = coupons.filter((c) => c.requiresRedeemCode && c.issued);
  for (const coupon of redeemCoupons) {
    const rows: CardIssuanceCouponRedeemItemView[] = [];
    const tokenId = coupon.issuedTokenId?.trim() ?? '';
    for (const batch of batches) {
      if (batch.cardAddress.toLowerCase() !== addr) continue;
      if (batch.kind !== 'issued_nft_coupon') continue;
      const batchMatchesCoupon =
        batch.couponId === coupon.id ||
        (tokenId && batch.issuedNftTokenId?.trim() === tokenId && !batch.couponId);
      if (!batchMatchesCoupon) continue;
      for (const item of batch.items) {
        rows.push({
          ...item,
          createdAt: (item as CardIssuanceCouponRedeemItemView).createdAt ?? batch.createdAt,
          redeemedAt: (item as CardIssuanceCouponRedeemItemView).redeemedAt,
        });
      }
    }
    rows.sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0));
    map.set(coupon.id, rows);
  }
  return map;
}

function collectProductionRedeemRowsByProductionId(
  cardAddress: string | undefined,
  productions: CardIssuanceProductionRow[]
): Map<string, CardIssuanceCouponRedeemItemView[]> {
  const map = new Map<string, CardIssuanceCouponRedeemItemView[]>();
  const addr = cardAddress?.trim().toLowerCase();
  if (!addr) return map;
  const batches = ((CoNET_Data as { cardRedeems?: CardRedeemBatch[] } | null)?.cardRedeems ??
    []) as CardRedeemBatch[];
  const redeemProductions = productions.filter((p) => p.requiresRedeemCode && p.issued);
  for (const production of redeemProductions) {
    const rows: CardIssuanceCouponRedeemItemView[] = [];
    const tokenId = production.issuedTokenId?.trim() ?? '';
    for (const batch of batches) {
      if (batch.cardAddress.toLowerCase() !== addr) continue;
      if (batch.kind !== 'issued_nft_production') continue;
      const batchMatchesProduction =
        batch.productionId === production.id ||
        (tokenId && batch.issuedNftTokenId?.trim() === tokenId && !batch.productionId);
      if (!batchMatchesProduction) continue;
      for (const item of batch.items) {
        rows.push({
          ...item,
          createdAt: (item as CardIssuanceCouponRedeemItemView).createdAt ?? batch.createdAt,
          redeemedAt: (item as CardIssuanceCouponRedeemItemView).redeemedAt,
        });
      }
    }
    rows.sort((a, b) => (b.createdAt ?? 0) - (a.createdAt ?? 0));
    map.set(production.id, rows);
  }
  return map;
}

async function persistCouponRedeemRedeemedTimestamps(
  updates: { hash: string; redeemedAt: number }[]
): Promise<boolean> {
  if (updates.length === 0) return false;
  const prev = CoNET_Data;
  if (!prev?.cardRedeems?.length) return false;
  const updateMap = new Map(updates.map((u) => [u.hash, u.redeemedAt]));
  let changed = false;
  const nextBatches = prev.cardRedeems.map((batch) => ({
    ...batch,
    items: batch.items.map((item) => {
      const redeemedAt = updateMap.get(item.hash);
      const existing = (item as CardIssuanceCouponRedeemItemView).redeemedAt;
      if (redeemedAt && !existing) {
        changed = true;
        return { ...item, redeemedAt };
      }
      return item;
    }),
  }));
  if (!changed) return false;
  setCoNET_Data({ ...prev, cardRedeems: nextBatches });
  await storeSystemData();
  return true;
}

async function clearCouponRedeemRedeemedTimestamps(hashes: string[]): Promise<boolean> {
  if (hashes.length === 0) return false;
  const prev = CoNET_Data;
  if (!prev?.cardRedeems?.length) return false;
  const clearSet = new Set(hashes);
  let changed = false;
  const nextBatches = prev.cardRedeems.map((batch) => ({
    ...batch,
    items: batch.items.map((item) => {
      if (!clearSet.has(item.hash)) return item;
      const existing = (item as CardIssuanceCouponRedeemItemView).redeemedAt;
      if (!existing) return item;
      changed = true;
      const { redeemedAt: _drop, ...rest } = item as CardIssuanceCouponRedeemItemView;
      return rest;
    }),
  }));
  if (!changed) return false;
  setCoNET_Data({ ...prev, cardRedeems: nextBatches });
  await storeSystemData();
  return true;
}

function makeCardIssuanceBonusRuleRow(
  paymentAmount: number | string = CARD_ISSUANCE_BONUS_RULE_PAYMENT_DEFAULT,
  bonusValue: number | string = CARD_ISSUANCE_BONUS_RULE_BONUS_DEFAULT,
  bonusProportional = false
): CardIssuanceBonusRuleRow {
  return {
    id: `bonus-rule-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    paymentAmount: String(paymentAmount),
    bonusValue: String(bonusValue),
    bonusProportional,
  };
}

/** Prefer factory.latestCardOfOwner on CoNET (EOA before AA); ignore deprecated Base L2 program cards. */
async function pickPrimaryIssuedCardAddressForBiz(
  profile: { aaAccount?: string | null; keyID?: string | null; privateKeyArmor?: string | null },
  ownedCards: UserCardInfo[],
): Promise<string | null> {
  const fromFactory = await fetchLatestMerchantProgramCardAddressForProfile(profile);
  if (fromFactory) return fromFactory;
  if (!ownedCards.length) return null;
  const conetCards: UserCardInfo[] = [];
  for (const c of ownedCards) {
    if (await isMerchantUserCardOnConet(c.cardAddress)) conetCards.push(c);
  }
  if (!conetCards.length) return null;
  return ethers.getAddress(conetCards[conetCards.length - 1]!.cardAddress);
}

async function bizProgramCardReadProvider(cardAddress: string): Promise<ethers.Provider> {
  return (await providerForBeamioUserCard(cardAddress)).provider;
}

