const merchantPanelDiscoverAssetLabel = useMemo(() => {
  const metaTiers = programsOverviewTiersSortedAscending;
  if (metaTiers.length > 0) {
    const top = metaTiers[metaTiers.length - 1];
    const name = (top.name ?? '').trim();
    const minRaw = top.minUsdc6 != null && String(top.minUsdc6).trim() !== '' ? String(top.minUsdc6) : '';
    let minDisplay = '';
    if (minRaw) {
      try {
        minDisplay = `${cardIssuanceDisplayMoneyPrefix}${Number(ethers.formatUnits(minRaw, 6)).toFixed(2)}`;
      } catch {
        minDisplay = '';
      }
    }
    if (name && minDisplay) return `${name} · ${minDisplay}`;
    if (name) return name;
    if (minDisplay) return minDisplay;
  }
  if (cardIssuanceTopupPromotionPayload) {
    return formatTopupPromotionDisplay(cardIssuanceTopupPromotionPayload, cardIssuanceDisplayMoneyPrefix);
  }
  return tu('member_benefits');
}, [programsOverviewTiersSortedAscending, cardIssuanceDisplayMoneyPrefix, cardIssuanceTopupPromotionPayload]);

useEffect(() => {
  if (
    !cardIssuanceTopupPromotionEditorOpen &&
    !cardIssuanceTierEditorOpen &&
    !cardIssuanceSocialPromotionEditorOpen &&
    !cardIssuanceConsumptionPointEditorOpen &&
    !cardIssuanceCouponSocialPromotionEditorOpenId &&
    !cardIssuanceSocialExchangeEditorOpen &&
    !cardIssuanceCardBackgroundDrawerOpen
  ) {
    return;
  }
  const prevOverflow = document.body.style.overflow;
  document.body.style.overflow = 'hidden';
  return () => {
    document.body.style.overflow = prevOverflow;
  };
}, [
  cardIssuanceTopupPromotionEditorOpen,
  cardIssuanceTierEditorOpen,
  cardIssuanceSocialPromotionEditorOpen,
  cardIssuanceConsumptionPointEditorOpen,
  cardIssuanceCouponSocialPromotionEditorOpenId,
  cardIssuanceSocialExchangeEditorOpen,
  cardIssuanceCardBackgroundDrawerOpen,
]);

const cardIssuanceTierEditorThresholdInt = useMemo(() => {
  const raw = cardIssuanceTierEditorThreshold.replace(/,/g, '').trim();
  const n = Number.parseInt(raw, 10);
  return Number.isFinite(n) ? n : null;
}, [cardIssuanceTierEditorThreshold]);

const cardIssuanceTierEditorValidationError = useMemo(() => {
  const name = cardIssuanceTierEditorName.trim();
  if (!name) return 'Tier name is required.';
  if (cardIssuanceTierEditorThresholdInt == null || cardIssuanceTierEditorThresholdInt <= 0) {
    return 'Enter a valid minimum spending amount.';
  }
  const minTopupN = cardIssuanceTierThresholdToInt(cardIssuanceMinTopup);
  const editingBaseTier = cardIssuanceEditingTierId === CARD_ISSUANCE_SINGLE_TIER_ID;
  if (editingBaseTier && cardIssuanceTierEditorThresholdInt < cardIssuanceMinTopupCurrencyFloor) {
    return `Base Tier must be at least ${cardIssuanceMinTopupFloorLabel}.`;
  }
  if (!editingBaseTier && cardIssuanceTierEditorThresholdInt <= minTopupN) {
    return 'Reward tiers must be above the Base minimum spending amount.';
  }
  const otherThresholds = cardIssuanceTiers
    .filter((tier) => tier.id !== cardIssuanceEditingTierId)
    .map((tier) => cardIssuanceTierThresholdToInt(tier.threshold));
  if (otherThresholds.includes(cardIssuanceTierEditorThresholdInt)) {
    return 'Another tier already uses this minimum spending amount.';
  }
  return '';
}, [
  cardIssuanceEditingTierId,
  cardIssuanceMinTopup,
  cardIssuanceMinTopupCurrencyFloor,
  cardIssuanceMinTopupFloorLabel,
  cardIssuanceTierEditorName,
  cardIssuanceTierEditorThresholdInt,
  cardIssuanceTiers,
]);

const openCardIssuanceTierCreate = useCallback(() => {
  const template = nextCardIssuanceTierTemplate(cardIssuanceTiers, cardIssuanceMinTopup);
  setCardIssuanceEditingTierId(null);
  setCardIssuanceTierEditorName(template.name);
  setCardIssuanceTierEditorThreshold(template.threshold);
  setCardIssuanceTierEditorBackgroundColor(template.backgroundColor);
  setCardIssuanceTierEditorDescription(template.tierDescription);
  setCardIssuanceTierEditorPreset(template.preset);
  setCardIssuanceTierEditorOpen(true);
}, [cardIssuanceMinTopup, cardIssuanceTiers]);

const openCardIssuanceTierEdit = useCallback((tierId: string) => {
  const row = cardIssuanceTiers.find((tier) => tier.id === tierId);
  if (!row) return;
  setCardIssuanceEditingTierId(tierId);
  setCardIssuanceTierEditorName(row.name);
  setCardIssuanceTierEditorThreshold(row.threshold);
  setCardIssuanceTierEditorBackgroundColor(
    tierBackgroundColorForPayload(row.backgroundColor) ??
      (row.backgroundColor.trim().startsWith('#') ? row.backgroundColor.trim().slice(0, 7) : '#6366f1')
  );
  setCardIssuanceTierEditorDescription(row.tierDescription);
  setCardIssuanceTierEditorPreset(row.preset);
  setCardIssuanceTierEditorOpen(true);
}, [cardIssuanceTiers]);

const closeCardIssuanceTierEditor = useCallback(() => {
  setCardIssuanceTierEditorOpen(false);
  setCardIssuanceEditingTierId(null);
}, []);

const applyCardIssuanceTierEditor = useCallback(async () => {
  if (cardIssuanceTierEditorValidationError) return;
  if (cardIssuanceCreateLoading) return;
  const nextMinTopup =
    cardIssuanceEditingTierId === CARD_ISSUANCE_SINGLE_TIER_ID
      ? String(cardIssuanceTierEditorThresholdInt ?? cardIssuanceMinTopupCurrencyFloor)
      : cardIssuanceMinTopup;
  const nextRow = makeCardIssuanceTierRow({
    id: cardIssuanceEditingTierId ?? undefined,
    name: cardIssuanceTierEditorName.trim(),
    preset: cardIssuanceTierEditorPreset,
    threshold: String(cardIssuanceTierEditorThresholdInt ?? ''),
    discountPercent: '0',
    tierDescription:
      cardIssuanceEditingTierId === CARD_ISSUANCE_SINGLE_TIER_ID
        ? ''
        : cardIssuanceTierEditorDescription.slice(0, CARD_ISSUANCE_CONFIGURATION_MAX_CHARS),
    backgroundColor: cardIssuanceTierEditorBackgroundColor,
    backgroundImage:
      (cardIssuanceEditingTierId
        ? cardIssuanceTiers.find((tier) => tier.id === cardIssuanceEditingTierId)?.backgroundImage
        : '') ?? '',
    backgroundImageFit:
      (cardIssuanceEditingTierId
        ? cardIssuanceTiers.find((tier) => tier.id === cardIssuanceEditingTierId)?.backgroundImageFit
        : undefined) ?? 'width',
    logoDisplayScale:
      (cardIssuanceEditingTierId
        ? cardIssuanceTiers.find((tier) => tier.id === cardIssuanceEditingTierId)?.logoDisplayScale
        : undefined) ?? TIER_LOGO_DISPLAY_SCALE_DEFAULT,
    tierDescriptionOpen: false,
  });
    const merged = cardIssuanceEditingTierId
    ? cardIssuanceTiers.map((tier) => (tier.id === cardIssuanceEditingTierId ? nextRow : tier))
    : [...cardIssuanceTiers, nextRow];
  const nextTiers = reconcileTierThresholdsWithMinTopup(merged, nextMinTopup);
  setCardIssuanceTiers(nextTiers);
  if (cardIssuanceEditingTierId === CARD_ISSUANCE_SINGLE_TIER_ID) {
    setCardIssuanceMinTopup(nextMinTopup);
  }
  setCardIssuanceTierEditorOpen(false);
  setCardIssuanceEditingTierId(null);

  if (cardIssuanceExistingCard?.cardAddress) {
    await handlePublishCardIssuanceRef.current({
      tiersOverride: nextTiers,
      minTopupOverride: nextMinTopup,
    });
  }
}, [
  cardIssuanceCreateLoading,
  cardIssuanceEditingTierId,
  cardIssuanceExistingCard?.cardAddress,
  cardIssuanceMinTopup,
  cardIssuanceMinTopupCurrencyFloor,
  cardIssuanceTiers,
  cardIssuanceTierEditorBackgroundColor,
  cardIssuanceTierEditorDescription,
  cardIssuanceTierEditorName,
  cardIssuanceTierEditorPreset,
  cardIssuanceTierEditorThresholdInt,
  cardIssuanceTierEditorValidationError,
]);

const removeCardIssuanceTierFromEditor = useCallback(async () => {
  if (!cardIssuanceEditingTierId || cardIssuanceEditingTierId === CARD_ISSUANCE_SINGLE_TIER_ID) return;
  if (cardIssuanceCreateLoading) return;
  const nextTiers = reconcileTierThresholdsWithMinTopup(
    cardIssuanceTiers.filter((tier) => tier.id !== cardIssuanceEditingTierId),
      cardIssuanceMinTopup
  );
  setCardIssuanceTiers(nextTiers);
  setCardIssuanceTierEditorOpen(false);
  setCardIssuanceEditingTierId(null);

  if (cardIssuanceExistingCard?.cardAddress) {
    await handlePublishCardIssuanceRef.current({
      tiersOverride: nextTiers,
      minTopupOverride: cardIssuanceMinTopup,
    });
  }
}, [
  cardIssuanceCreateLoading,
  cardIssuanceEditingTierId,
  cardIssuanceExistingCard?.cardAddress,
  cardIssuanceMinTopup,
  cardIssuanceTiers,
]);

