const openCardIssuanceProductionEdit = useCallback(
  (productionId: string) => {
    let row = cardIssuanceProductions.find((item) => item.id === productionId);
    if (!row) return;
    if (isCatalogPackageDealRow(row)) {
      const parentToken = row.packageParentTokenId?.trim();
      const parentProductionId = row.packageParentProductionId?.trim();
      const parent =
        (parentToken
          ? cardIssuanceProductions.find((item) => item.issuedTokenId?.trim() === parentToken)
          : undefined) ??
        (parentProductionId
          ? cardIssuanceProductions.find((item) => item.id === parentProductionId)
          : undefined);
      if (!parent) return;
      row = parent;
      productionId = parent.id;
    }
    setCardIssuanceProductionEditorError('');
    setCardIssuanceEditingProductionId(productionId);
    setCardIssuanceProductionName(row.name);
    setCardIssuanceProductionSubtitle(row.subtitle);
    setCardIssuanceProductionGlobalCategory(row.globalCategory);
    setCardIssuanceProductionItemCategory(row.itemCategory);
    const displayPrice = catalogProductionDisplayPrice(row);
    setCardIssuanceProductionPrice(
      displayPrice != null ? String(displayPrice) : row.singleSessionPrice || '0'
    );
    setCardIssuanceProductionIssueTotal(
      row.issueTotal || String(CARD_ISSUANCE_PRODUCTION_ISSUE_TOTAL_DEFAULT)
    );
    setCardIssuanceProductionIssueTotalUnlimited(row.issueTotalUnlimited === true);
    setCardIssuanceProductionRequiresRedeemCode(row.requiresRedeemCode === true);
    setCardIssuanceProductionDescription(row.description);
    setCardIssuanceProductionIcon(row.icon || '');
    setCardIssuanceProductionImage((row.productionImage ?? '').trim());
    setCardIssuanceProductionImageMime((row.productionImageMime ?? '').trim());
    setCardIssuanceProductionImageStartSec(row.productionImageStartSec ?? 0);
    revokeProductionVideoDraft();
    setCardIssuanceProductionBackgroundColor(
      tierBackgroundColorForPayload(row.backgroundColor) ?? (row.backgroundColor.trim() || '#ea580c')
    );
    setCardIssuanceProductionPackageDeals(
      catalogPackageDealsForBase(cardIssuanceProductions, row).map(packageDealDraftFromProductionRow)
    );
    setCardIssuanceProductionEditorOpen(true);
  },
  [cardIssuanceProductions, revokeProductionVideoDraft]
);

const closeCardIssuanceProductionEditor = useCallback(() => {
  setCardIssuanceProductionEditorOpen(false);
  setCardIssuanceEditingProductionId(null);
  resetCardIssuanceProductionEditorFields();
  setCardIssuanceProductionEditorError('');
}, [resetCardIssuanceProductionEditorFields]);

const removeCardIssuanceProductionDraft = useCallback(
  async (productionId: string) => {
    const nextProductions = cardIssuanceProductions.filter((item) => {
      if (item.id === productionId && !item.issued) return false;
      if (!item.issued && item.packageParentProductionId?.trim() === productionId) return false;
      return true;
    });
    setCardIssuanceProductions(nextProductions);
    if (cardIssuanceExistingCard?.cardAddress) {
      await handlePublishCardIssuanceRef.current({
        productionsOverride: nextProductions,
        loadingScope: 'default',
      });
    }
  },
  [cardIssuanceExistingCard?.cardAddress, cardIssuanceProductions]
);

const runProductionVideoConvertAndUpload = useCallback(
  async (args: {
    file: File;
    startSec: number;
    sourceDurationSec?: number;
  }): Promise<{ ok: true; imageUrl: string; mime: string } | { ok: false }> => {
    const p0 = profiles?.[0];
    if (!p0?.privateKeyArmor) {
      setCardIssuanceProductionEditorError(
        'Profile not available for upload. Open Settings and ensure your wallet is ready.'
      );
      return { ok: false };
    }
    productionVideoUploadAbortRef.current?.abort();
    const abortController = new AbortController();
    productionVideoUploadAbortRef.current = abortController;

    setCardIssuanceProductionEditorError('');
    setCardIssuanceProductionImageUploading(true);
    setProductionVideoFfmpegBusy(true);
    setProductionVideoUploadProgress(0);
    setProductionVideoProcessingMessage('Preparing video…');
    try {
      let convertWorkflow = 'Preparing video…';
      const mapUploadProgress = (progress: IpfsFragmentUploadProgress) => {
        if (progress.phase === 'prepare') {
          setProductionVideoUploadProgress(34);
          setProductionVideoProcessingMessage(progress.message);
          return;
        }
        const pct = 35 + Math.round(progress.percent * 0.65);
        setProductionVideoUploadProgress(Math.min(100, pct));
        setProductionVideoProcessingMessage(progress.message);
      };

      const standardized = await standardizeProductionBackgroundVideo({
        file: args.file,
        startSec: args.startSec,
        sourceDurationSec:
          args.sourceDurationSec != null && args.sourceDurationSec > 0
            ? args.sourceDurationSec
            : productionVideoSourceDurationSec > 0
              ? productionVideoSourceDurationSec
              : undefined,
        onStatus: (message) => {
          convertWorkflow = message;
          setProductionVideoProcessingMessage(message);
          if (/loading video processor/i.test(message)) {
            setProductionVideoUploadProgress(6);
          } else if (/no re-encode|no conversion needed/i.test(message)) {
            setProductionVideoUploadProgress(28);
          } else if (/hardware accelerator|encoding with/i.test(message)) {
            setProductionVideoUploadProgress(10);
          } else if (/optimizing video/i.test(message)) {
            setProductionVideoUploadProgress(32);
          }
        },
        onConvertProgress: (ratio) => {
          setProductionVideoProcessingMessage(convertWorkflow);
          setProductionVideoUploadProgress(8 + Math.round(Math.min(1, Math.max(0, ratio)) * 24));
        },
      });
      if (abortController.signal.aborted) return { ok: false };

      setProductionVideoFfmpegBusy(false);
      adoptProductionVideoDraftStandardizedClip(standardized.file);

      const hash = await uploadMediaFileToIpfsChunked(
        p0,
        standardized.file,
        mapUploadProgress,
        abortController.signal
      );
      if (!hash) {
        setCardIssuanceProductionEditorError('Background video upload failed.');
        return { ok: false };
      }
      const imageUrl = ipfsFragmentUrlFromHash(hash);
      setProductionVideoUploadProgress(100);
      setCardIssuanceProductionImage(imageUrl);
      setCardIssuanceProductionImageMime('video/mp4');
      setCardIssuanceProductionImageStartSec(0);
      // Keep draft blob + standardized File for catalog preview picker (browser decode, no 2nd ffmpeg pass).
      return { ok: true, imageUrl, mime: 'video/mp4' };
    } catch (err: unknown) {
      if (abortController.signal.aborted) return { ok: false };
      setCardIssuanceProductionEditorError(
        err instanceof Error ? err.message : 'Background video processing failed.'
      );
      return { ok: false };
    } finally {
      if (productionVideoUploadAbortRef.current === abortController) {
        productionVideoUploadAbortRef.current = null;
      }
      setProductionVideoProcessingMessage('');
      setProductionVideoFfmpegBusy(false);
      setCardIssuanceProductionImageUploading(false);
    }
  },
  [profiles, productionVideoSourceDurationSec, adoptProductionVideoDraftStandardizedClip, revokeProductionVideoDraftPreviewUrl]
);

const startProductionVideoUploadAfterTrim = useCallback(async () => {
  const file = productionVideoDraftFile;
  if (!file || cardIssuanceProductionImageUploading) return;
  await runProductionVideoConvertAndUpload({
    file,
    startSec: productionVideoStartSec,
    sourceDurationSec: productionVideoSourceDurationSec > 0 ? productionVideoSourceDurationSec : undefined,
  });
}, [
  productionVideoDraftFile,
  productionVideoStartSec,
  productionVideoSourceDurationSec,
  cardIssuanceProductionImageUploading,
  runProductionVideoConvertAndUpload,
]);

const confirmProductionVideoTrimAndUpload = useCallback(() => {
  setProductionVideoTrimConfirmed(true);
  void startProductionVideoUploadAfterTrim();
}, [startProductionVideoUploadAfterTrim]);

const editProductionVideoTrim = useCallback(() => {
  if (cardIssuanceProductionImageUploading) {
    productionVideoUploadAbortRef.current?.abort();
    productionVideoUploadAbortRef.current = null;
    setCardIssuanceProductionImageUploading(false);
    setProductionVideoProcessingMessage('');
  }
  setProductionVideoTrimConfirmed(false);
  setProductionVideoUploadProgress(0);
}, [cardIssuanceProductionImageUploading]);

const submitCardIssuanceProductionEditor = useCallback(async () => {
  const editingExistingRow = cardIssuanceEditingProductionId
    ? cardIssuanceProductions.find((item) => item.id === cardIssuanceEditingProductionId) ?? null
    : null;
  const lockIssuedOnChainFields = Boolean(editingExistingRow?.issued);
  const name = lockIssuedOnChainFields
    ? (editingExistingRow?.name?.trim() ?? '')
    : cardIssuanceProductionName.trim();
  const subtitle = lockIssuedOnChainFields
    ? (editingExistingRow?.subtitle ?? '')
    : cardIssuanceProductionSubtitle.trim();
  const globalCategory = lockIssuedOnChainFields
    ? editingExistingRow?.globalCategory ?? DEFAULT_CATALOG_GLOBAL_CATEGORY
    : cardIssuanceProductionGlobalCategory;
  const salesManagementItem = isSalesManagementCatalogCategory(globalCategory);
  const shareLinkItem = isShareLinkCatalogCategory(globalCategory);
  const priceOptionalItem = isCatalogPriceOptionalCategory(globalCategory);
  const itemCategory = lockIssuedOnChainFields
    ? editingExistingRow?.itemCategory ?? DEFAULT_PRODUCTION_SERVICE_CATEGORY_OPTIONS[0].id
    : cardIssuanceProductionItemCategory;
  const singleSessionPrice = lockIssuedOnChainFields
    ? (editingExistingRow?.singleSessionPrice ?? '0')
    : priceOptionalItem
      ? '0'
      : cardIssuanceProductionPrice.trim() || '0';
  const issueTotalUnlimited = lockIssuedOnChainFields
    ? editingExistingRow?.issueTotalUnlimited === true
    : shareLinkItem
      ? true
      : salesManagementItem
        ? false
        : cardIssuanceProductionIssueTotalUnlimited;
  const issueTotal = lockIssuedOnChainFields
    ? (editingExistingRow?.issueTotal ?? String(CARD_ISSUANCE_PRODUCTION_ISSUE_TOTAL_DEFAULT))
    : cardIssuanceProductionIssueTotal.trim();
  const description = cardIssuanceProductionDescription.trim();
  const icon = cardIssuanceProductionIcon.trim();
  let productionImage = cardIssuanceProductionImage.trim();
  let productionImageMime = cardIssuanceProductionImageMime.trim();
  let productionImageStartSec =
    cardIssuanceProductionImageStartSec > 0 ? cardIssuanceProductionImageStartSec : undefined;
  const backgroundColor =
    tierBackgroundColorForPayload(cardIssuanceProductionBackgroundColor.trim()) ?? '#ea580c';
  rememberCardIssuanceProductionLastIconInput(icon, cardIssuanceProductionLastIconRef);

  if (!name) {
    setCardIssuanceProductionEditorError('Service name is required.');
    return;
  }
  if (!lockIssuedOnChainFields && !priceOptionalItem) {
    const chargeAmount = productionEffectiveChargeAmount({
      packageDealEnabled: false,
      singleSessionPrice,
      packageTotalPrice: '0',
    });
    if (chargeAmount <= 0) {
      setCardIssuanceProductionEditorError('Price must be greater than 0.');
      return;
    }
  }
  const packageDealsForSubmit = priceOptionalItem ? [] : cardIssuanceProductionPackageDeals;
  for (const deal of packageDealsForSubmit) {
    const packageErr = validateCatalogPackageDealDraft(deal);
    if (packageErr) {
      setCardIssuanceProductionEditorError(packageErr);
      return;
    }
  }
  if (!issueTotalUnlimited) {
    const issueTotalRaw = issueTotal.replace(/,/g, '').trim();
    const issueTotalN = Number.parseInt(issueTotalRaw, 10);
    const issueTotalAsFloat = Number.parseFloat(issueTotalRaw);
    if (
      !issueTotalRaw ||
      !Number.isFinite(issueTotalAsFloat) ||
      !Number.isFinite(issueTotalN) ||
      issueTotalAsFloat !== issueTotalN ||
      issueTotalN < 1 ||
      issueTotalN > CARD_ISSUANCE_PRODUCTION_ISSUE_TOTAL_MAX
    ) {
      setCardIssuanceProductionEditorError(
        `Total issuance must be a whole number from 1 to ${CARD_ISSUANCE_PRODUCTION_ISSUE_TOTAL_MAX.toLocaleString()}.`
      );
      return;
    }
  }
  setCardIssuanceProductionEditorError('');

  if (productionVideoClipEditRequired && !productionImage) {
    if (cardIssuanceProductionImageUploading) {
      setCardIssuanceProductionEditorError('Video upload is still in progress.');
      return;
    }
    setCardIssuanceProductionEditorError('Confirm your trim and wait for the video upload to finish.');
    return;
  }

  const issueTotalFixed = issueTotalUnlimited
    ? String(CARD_ISSUANCE_PRODUCTION_ISSUE_TOTAL_MAX)
    : String(Number.parseInt(issueTotal.replace(/,/g, '').trim(), 10));

  const requiresRedeemCodeFinal = lockIssuedOnChainFields
    ? editingExistingRow?.requiresRedeemCode === true
    : shareLinkItem
      ? false
      : salesManagementItem
        ? cardIssuanceProductionRequiresRedeemCode
        : false;

  const baseRow = makeCardIssuanceProductionRow({
    id: editingExistingRow?.id,
    name,
    subtitle,
    globalCategory,
    itemCategory,
    singleSessionPrice,
    packageDealEnabled: false,
    packageSessions: '10',
    packageBonusSessions: '1',
    packageTotalPrice: '0',
    issueTotal: issueTotalFixed,
    issueTotalUnlimited,
    requiresRedeemCode: requiresRedeemCodeFinal,
    icon,
    backgroundColor,
    productionImage,
    ...(productionImageMime ? { productionImageMime } : {}),
    ...(productionImageStartSec != null ? { productionImageStartSec } : {}),
    description,
    issued: editingExistingRow?.issued === true,
    ...(editingExistingRow?.issuedTokenId ? { issuedTokenId: editingExistingRow.issuedTokenId } : {}),
  });

  const buildPackageRowsForBase = (parent: CardIssuanceProductionRow): CardIssuanceProductionRow[] =>
    packageDealsForSubmit.map((deal) => {
      if (deal.issued) {
        const existing = cardIssuanceProductions.find((item) => item.id === deal.id);
        if (existing) {
          return {
            ...existing,
            name: parent.name,
            subtitle: parent.subtitle,
            globalCategory: parent.globalCategory,
            itemCategory: parent.itemCategory,
            icon: parent.icon,
            backgroundColor: parent.backgroundColor,
            productionImage: parent.productionImage,
            ...(parent.productionImageMime?.trim()
              ? { productionImageMime: parent.productionImageMime.trim() }
              : {}),
            ...(parent.productionImageStartSec != null && parent.productionImageStartSec > 0
              ? { productionImageStartSec: parent.productionImageStartSec }
              : {}),
            description: parent.description,
            issueTotal: parent.issueTotal,
            issueTotalUnlimited: parent.issueTotalUnlimited,
          };
        }
      }
      const parentToken = parent.issuedTokenId?.trim() ?? '';
      if (parentToken) {
        return buildPackageProductionRowFromBase(parent, deal, parentToken);
      }
      return buildPackageProductionDraftRowFromBase(parent, deal);
    });

  const mergeCatalogBaseAndPackageRows = (
    prev: CardIssuanceProductionRow[],
    parent: CardIssuanceProductionRow,
    packageRows: CardIssuanceProductionRow[]
  ): CardIssuanceProductionRow[] => {
    const withoutLinked = prev.filter((item) => {
      if (item.id === parent.id) return false;
      if (!isCatalogPackageDealRow(item)) return true;
      if (item.packageParentProductionId?.trim() === parent.id) return false;
      const parentToken = parent.issuedTokenId?.trim();
      if (parentToken && item.packageParentTokenId?.trim() === parentToken) return false;
      return true;
    });
    return [...withoutLinked, parent, ...packageRows];
  };

  const issueCatalogProductionNftOnChain = async (
    row: CardIssuanceProductionRow,
    cardAddr: string,
    ownerKey: string
  ): Promise<{
    row: CardIssuanceProductionRow | null;
    redeemErr?: string;
    redeemInitialBatch?: number;
  }> => {
    const issueTotalForRow = computeProductionIssueTotalN(row);
    const catalogPublisherBeamioTag =
      beamio?.accountName?.trim() ||
      (profiles?.[0] as { username?: string; accountName?: string } | undefined)?.username ||
      (profiles?.[0] as { accountName?: string } | undefined)?.accountName ||
      '';
    const metaProps = buildProductionIssuedNftMetaProps(row, {
      publisherBeamioTag: catalogPublisherBeamioTag,
    });
    const nftData = encodeCreateIssuedNft(row.name.trim(), 0, 0, issueTotalForRow, 0, '0');
    const deadline = Math.floor(Date.now() / 1000) + 3600;
    const nonce = ethers.hexlify(ethers.randomBytes(32));
    const ownerSig = await signExecuteForOwner(ownerKey, cardAddr, nftData, deadline, nonce);
    const descFirst =
      row.description.trim() ||
      (row.packageDealEnabled
        ? `Program package: ${row.name.trim()}`
        : `Program service: ${row.name.trim()}`);
    const createRes = await postCardCreateIssuedNft({
      cardAddress: cardAddr,
      data: nftData,
      deadline,
      nonce,
      ownerSignature: ownerSig,
      description: descFirst,
      background_color: row.backgroundColor.trim() || '#ea580c',
      metadata_extra_properties: metaProps,
    });
    if (!createRes.success) {
      setCardIssuanceProductionEditorError(createRes.error ?? 'Failed to create catalog NFT on-chain.');
      return { row: null };
    }
    const issuedRaw = createRes.issuedNftTokenId?.trim();
    if (!issuedRaw) {
      setCardIssuanceProductionEditorError(
        'Catalog NFT was submitted but the server did not return issuedNftTokenId. Please retry.'
      );
      return { row: null };
    }
    let newTokenId: bigint;
    try {
      newTokenId = BigInt(issuedRaw);
    } catch {
      setCardIssuanceProductionEditorError('Server returned an invalid issuedNftTokenId. Please retry.');
      return { row: null };
    }
    const tokenIdStr = String(newTokenId);
    void postRegisterIssuedNftSeries({
      cardAddress: cardAddr,
      tokenId: tokenIdStr,
      metadata: {
        ...metaProps,
        productionId: row.id,
        issuedTokenId: tokenIdStr,
      },
    }).catch(() => {});

    let redeemErr: string | undefined;
    let redeemInitialBatch = 0;
    if (row.requiresRedeemCode) {
      redeemInitialBatch = initialRedeemRegisterBatchCount(issueTotalForRow);
      const codes: string[] = [];
      const redeemItems: CardIssuanceCouponRedeemItemView[] = [];
      const generatedAt = Date.now();
      for (let i = 0; i < redeemInitialBatch; i++) {
        const { code } = generateCODE('');
        codes.push(code);
        redeemItems.push({
          code,
          hash: chainHashForRedeemCode(code),
          createdAt: generatedAt,
        });
      }
      const { validAfter, validBefore } = redeemValidityForCoupon('none', '', '');
      const rDeadline = Math.floor(Date.now() / 1000) + 3600;
      const rNonce = ethers.hexlify(ethers.randomBytes(32));
      const redeemData = encodeCreateRedeemBatchBundle(
        codes,
        0n,
        0,
        validAfter,
        validBefore,
        [newTokenId],
        [1n]
      );
      const redeemSig = await signExecuteForOwner(ownerKey, cardAddr, redeemData, rDeadline, rNonce);
      const redeemRes = await postCardCreateRedeem({
        cardAddress: cardAddr,
        codes,
        points6: '0',
        validAfter,
        validBefore,
        deadline: rDeadline,
        nonce: rNonce,
        ownerSignature: redeemSig,
        tokenIds: [tokenIdStr],
        amounts: ['1'],
        attr: 0,
      });
      if (!redeemRes.success || !redeemRes.codes) {
        redeemErr =
          redeemRes.error ??
          'Catalog NFT was created but redeem codes could not be registered. Register more from the catalog list.';
      } else {
        const batch: CardRedeemBatch = {
          batchId: `production-${row.id}-${Date.now()}`,
          cardAddress: cardAddr,
          points6: '0',
          pointsHuman: '1 NFT',
          createdAt: generatedAt,
          kind: 'issued_nft_production',
          issuedNftTokenId: tokenIdStr,
          productionId: row.id,
          items: redeemItems,
        };
        const prev = CoNET_Data;
        if (prev) {
          const updatedList: CardRedeemBatch[] = [
            ...(((prev as { cardRedeems?: CardRedeemBatch[] }).cardRedeems ?? []) as CardRedeemBatch[]),
            batch,
          ];
          setCoNET_Data({ ...prev, cardRedeems: updatedList } as typeof prev);
          await storeSystemData();
          setCardIssuanceCouponRedeemsVersion((v) => v + 1);
        }
      }
    }

    return {
      row: {
        ...row,
        issued: true,
        issuedTokenId: tokenIdStr,
        requiresRedeemCode: row.requiresRedeemCode,
      },
      redeemErr,
      redeemInitialBatch,
    };
  };

  const packageRowsDraft = buildPackageRowsForBase(baseRow);

  if (cardIssuanceEditingProductionId) {
    let nextProductions = mergeCatalogBaseAndPackageRows(
      cardIssuanceProductions,
      baseRow,
      packageRowsDraft
    );
    setCardIssuanceProductions(nextProductions);

    if (cardIssuanceExistingCard?.cardAddress) {
      const p0 = profiles?.[0];
      if (!p0?.privateKeyArmor?.trim()) {
        setCardIssuanceProductionEditorError(
          'Unlock your wallet; program owner key is required to issue package deals.'
        );
        return;
      }
      setCardIssuanceProductionEditorPublishing(true);
      try {
        const cardAddr = ethers.getAddress(cardIssuanceExistingCard.cardAddress);
        const wallet = new ethers.Wallet(p0.privateKeyArmor.trim());
        const chainOwner = ethers.getAddress(
          await withPromiseTimeout(getCardOwner(cardAddr), 20_000, 'card.owner()')
        );
        if (chainOwner !== ethers.getAddress(wallet.address)) {
          setCardIssuanceProductionEditorError(
            'Package issuance requires the Beamio program card owner wallet. Switch to owner in Wallet, then retry.'
          );
          return;
        }

        if (baseRow.issued && baseRow.issuedTokenId?.trim()) {
          const issuedPackages: CardIssuanceProductionRow[] = [];
          for (const pkgRow of packageRowsDraft) {
            if (pkgRow.issued) {
              issuedPackages.push(pkgRow);
              continue;
            }
            const issuedPkgRes = await issueCatalogProductionNftOnChain(
              pkgRow,
              cardAddr,
              p0.privateKeyArmor.trim()
            );
            if (!issuedPkgRes.row) return;
            issuedPackages.push(issuedPkgRes.row);
          }
          nextProductions = mergeCatalogBaseAndPackageRows(nextProductions, baseRow, issuedPackages);
          setCardIssuanceProductions(nextProductions);
        }

        let publishMetadataError = '';
        const ok = await handlePublishCardIssuanceRef.current({
          productionsOverride: nextProductions,
          loadingScope: 'bonusEditor',
          metadataOnly: true,
          publishErrorSink: (message) => {
            publishMetadataError = message;
          },
        });
        if (!ok) {
          setCardIssuanceProductionEditorError(
            publishMetadataError ||
              'Could not save service changes. Fix any publish validation errors and try again.'
          );
        } else {
          const productionsPayload = buildCardIssuanceProductionMetadataPayload(nextProductions);
          if (productionsPayload?.length) {
            setCardIssuanceExistingCard((prev) => {
              if (!prev?.meta) return prev;
              return { ...prev, meta: { ...prev.meta, productions: productionsPayload } };
            });
          }
          setCardIssuanceProductionEditorOpen(false);
          setCardIssuanceEditingProductionId(null);
          resetCardIssuanceProductionEditorFields();
        }
      } catch (e: unknown) {
        setCardIssuanceProductionEditorError(e instanceof Error ? e.message : String(e));
      } finally {
        setCardIssuanceProductionEditorPublishing(false);
      }
    } else {
      setCardIssuanceProductionEditorOpen(false);
      setCardIssuanceEditingProductionId(null);
      resetCardIssuanceProductionEditorFields();
    }
    return;
  }

  if (!cardIssuanceExistingCard?.cardAddress) {
    let nextProductions: CardIssuanceProductionRow[] = [];
    setCardIssuanceProductions((prev) => {
      nextProductions = mergeCatalogBaseAndPackageRows(prev, baseRow, packageRowsDraft);
      return nextProductions;
    });
    setCardIssuanceProductionEditorOpen(false);
    setCardIssuanceEditingProductionId(null);
    resetCardIssuanceProductionEditorFields();
    return;
  }

  const p0 = profiles?.[0];
  if (!p0?.privateKeyArmor?.trim()) {
    setCardIssuanceProductionEditorError('Unlock your wallet; program owner key is required to issue services.');
    return;
  }

  setCardIssuanceProductionEditorPublishing(true);
  try {
    const cardAddr = ethers.getAddress(cardIssuanceExistingCard.cardAddress);
    const wallet = new ethers.Wallet(p0.privateKeyArmor.trim());
    const chainOwner = ethers.getAddress(
      await withPromiseTimeout(getCardOwner(cardAddr), 20_000, 'card.owner()')
    );
    if (chainOwner !== ethers.getAddress(wallet.address)) {
      setCardIssuanceProductionEditorError(
        'Service issuance requires the Beamio program card owner wallet. Switch to owner in Wallet, then retry.'
      );
      return;
    }

    const issuedBaseRes = await issueCatalogProductionNftOnChain(
      baseRow,
      cardAddr,
      p0.privateKeyArmor.trim()
    );
    if (!issuedBaseRes.row) return;
    const issuedBase = issuedBaseRes.row;

    const parentToken = issuedBase.issuedTokenId?.trim() ?? '';
    const issuedPackages: CardIssuanceProductionRow[] = [];
    for (const deal of cardIssuanceProductionPackageDeals) {
      const pkgRow = buildPackageProductionRowFromBase(issuedBase, deal, parentToken);
      const issuedPkgRes = await issueCatalogProductionNftOnChain(
        pkgRow,
        cardAddr,
        p0.privateKeyArmor.trim()
      );
      if (!issuedPkgRes.row) return;
      issuedPackages.push(issuedPkgRes.row);
    }

    const nextProductions = mergeCatalogBaseAndPackageRows(
      cardIssuanceProductions,
      issuedBase,
      issuedPackages
    );
    const productionsPayload = buildCardIssuanceProductionMetadataPayload(nextProductions);
    if (!productionsPayload?.length) {
      setCardIssuanceProductionEditorError(
        'Catalog item was issued on-chain, but program metadata could not be built (name is required).'
      );
      return;
    }
    setCardIssuanceProductions(nextProductions);
    let publishMetadataError = '';
    const metadataOk = await handlePublishCardIssuanceRef.current({
      productionsOverride: nextProductions,
      loadingScope: 'bonusEditor',
      metadataOnly: true,
      publishErrorSink: (message) => {
        publishMetadataError = message;
      },
    });
    if (metadataOk) {
      queueExplorerRefreshForIssuedProgramNfts(cardAddr, [], nextProductions);
      setCardIssuanceExistingCard((prev) => {
        if (!prev?.meta) return prev;
        return {
          ...prev,
          meta: {
            ...prev.meta,
            productions: productionsPayload,
          },
        };
      });
      setCardIssuanceProductionEditorOpen(false);
      setCardIssuanceEditingProductionId(null);
      resetCardIssuanceProductionEditorFields();
    } else {
      setCardIssuanceProductionEditorError(
        publishMetadataError ||
          'Service was saved on-chain, but updating share metadata failed. Try Publish again.'
      );
    }
    if (issuedBaseRes.redeemErr) {
      setCardIssuanceOwnerAdminNotice({ kind: 'warn', text: issuedBaseRes.redeemErr });
    } else if (
      issuedBase.requiresRedeemCode &&
      (issuedBaseRes.redeemInitialBatch ?? 0) > 0 &&
      computeProductionIssueTotalN(issuedBase) > (issuedBaseRes.redeemInitialBatch ?? 0)
    ) {
      setCardIssuanceOwnerAdminNotice({
        kind: 'ok',
        text: `Catalog item issued. Registered ${(issuedBaseRes.redeemInitialBatch ?? 0).toLocaleString()} redeem codes (max ${CARD_ISSUANCE_REDEEM_REGISTER_BATCH_MAX.toLocaleString()} per on-chain batch). Use + in the catalog list to register more while issuance remains.`,
      });
    }
  } catch (e: unknown) {
    setCardIssuanceProductionEditorError(e instanceof Error ? e.message : String(e));
  } finally {
    setCardIssuanceProductionEditorPublishing(false);
  }
}, [
  cardIssuanceExistingCard?.cardAddress,
  cardIssuanceProductionDescription,
  cardIssuanceProductionIcon,
  cardIssuanceProductionImage,
  cardIssuanceProductionImageMime,
  cardIssuanceProductionImageStartSec,
  cardIssuanceProductionBackgroundColor,
  cardIssuanceProductionName,
  cardIssuanceProductionPackageDeals,
  cardIssuanceProductionPrice,
  cardIssuanceProductionIssueTotal,
  cardIssuanceProductionIssueTotalUnlimited,
  cardIssuanceProductionRequiresRedeemCode,
  cardIssuanceProductionGlobalCategory,
  cardIssuanceProductionItemCategory,
  cardIssuanceProductionSubtitle,
  cardIssuanceEditingProductionId,
  cardIssuanceProductions,
  profiles,
  productionVideoClipEditRequired,
  cardIssuanceProductionImageUploading,
  resetCardIssuanceProductionEditorFields,
]);

const issueCardIssuanceCoupon = useCallback(async (couponId: string) => {
  const nextCoupons = cardIssuanceCoupons.map((item) => (item.id === couponId ? { ...item, issued: true } : item));
  setCardIssuanceCoupons(nextCoupons);
  if (cardIssuanceExistingCard?.cardAddress) {
    await handlePublishCardIssuanceRef.current({
      couponsOverride: nextCoupons,
      loadingScope: 'default',
    });
  }
}, [cardIssuanceExistingCard?.cardAddress, cardIssuanceCoupons]);

const toggleCardIssuanceCouponListed = useCallback(
  async (couponId: string, listed: boolean) => {
    const coupon = cardIssuanceCoupons.find((item) => item.id === couponId);
    if (!coupon?.issued || !coupon.issuedTokenId?.trim()) return;
    const cardAddrRaw = cardIssuanceExistingCard?.cardAddress?.trim() ?? '';
    if (!cardAddrRaw || !ethers.isAddress(cardAddrRaw)) return;

    setCardIssuanceCouponListingToggleId(couponId);
    try {
      const bgColor =
        effectiveTileBackgroundColorForMetadata({
          photo: coupon.couponImage,
          backgroundColor: coupon.backgroundColor,
        }) ??
        tierBackgroundColorForPayload(coupon.backgroundColor) ??
        '#0051d1';
      const res = await updateIssuedCouponMetadata({
        cardAddress: cardAddrRaw,
        couponId: coupon.id,
        issuedTokenId: coupon.issuedTokenId,
        icon: coupon.icon,
        backgroundColor: bgColor,
        description: coupon.description,
        couponImage: coupon.couponImage ?? '',
        disable: !listed,
      });
      if (!res.success) {
        setCardIssuanceOwnerAdminNotice({
          kind: 'warn',
          text: res.error ?? 'Failed to update coupon listing status.',
        });
        return;
      }
      setCardIssuanceCoupons((prev) =>
        prev.map((item) => (item.id === couponId ? { ...item, disabled: !listed } : item))
      );
      setCardIssuanceOwnerAdminNotice({
        kind: 'ok',
        text: listed
          ? 'Coupon is listed again for discovery and claim.'
          : 'Coupon delisted. Existing holders can still redeem at POS.',
      });
    } finally {
      setCardIssuanceCouponListingToggleId(null);
    }
  },
  [cardIssuanceCoupons, cardIssuanceExistingCard?.cardAddress]
);

const registerCardIssuanceCouponRedeemCodes = useCallback(
  async (couponId: string, requestedCount?: number) => {
    const coupon = cardIssuanceCoupons.find((item) => item.id === couponId);
    if (!coupon?.issued || !coupon.requiresRedeemCode) return;
    const issueLeftN = parseCardIssuanceCouponIssueLeftN(coupon);
    const batchCount = resolveRedeemRegisterBatchCount(
      issueLeftN,
      requestedCount,
      cardIssuanceCouponRedeemBatchQty[couponId]
    );
    if (batchCount <= 0) {
      setCardIssuanceOwnerAdminNotice({
        kind: 'warn',
        text: 'No remaining issuance left for this coupon.',
      });
      return;
    }
    const tokenIdStr = coupon.issuedTokenId?.trim() ?? '';
    if (!tokenIdStr) {
      setCardIssuanceOwnerAdminNotice({
        kind: 'warn',
        text: 'Coupon series id is not loaded yet. Wait for program data to finish loading, then try again.',
      });
      return;
    }
    const cardAddrRaw = cardIssuanceExistingCard?.cardAddress?.trim() ?? '';
    if (!cardAddrRaw || !ethers.isAddress(cardAddrRaw)) return;
    const p0 = profiles?.[0];
    if (!p0?.privateKeyArmor?.trim()) {
      setCardIssuanceOwnerAdminNotice({
        kind: 'warn',
        text: 'Unlock your wallet; program owner key is required to register redeem codes.',
      });
      return;
    }

    setCardIssuanceCouponRedeemRegisteringId(couponId);
    try {
      const cardAddr = ethers.getAddress(cardAddrRaw);
      const wallet = new ethers.Wallet(p0.privateKeyArmor.trim());
      const chainOwner = ethers.getAddress(
        await withPromiseTimeout(getCardOwner(cardAddr), 20_000, 'card.owner()')
      );
      if (chainOwner !== ethers.getAddress(wallet.address)) {
        setCardIssuanceOwnerAdminNotice({
          kind: 'warn',
          text: 'Registering redeem codes requires the Beamio program card owner wallet. Switch to owner in Wallet, then retry.',
        });
        return;
      }

      const codes: string[] = [];
      const redeemItems: CardIssuanceCouponRedeemItemView[] = [];
      const generatedAt = Date.now();
      for (let i = 0; i < batchCount; i++) {
        const { code } = generateCODE('');
        codes.push(code);
        redeemItems.push({
          code,
          hash: chainHashForRedeemCode(code),
          createdAt: generatedAt,
        });
      }
      const dr = coupon.couponDateRestriction === 'range' ? 'range' : 'none';
      const vfStore =
        dr === 'range' && parseCouponYmd(coupon.couponValidFromYmd)
          ? parseCouponYmd(coupon.couponValidFromYmd) ?? ''
          : '';
      const vtStore =
        dr === 'range' && parseCouponYmd(coupon.couponValidToYmd)
          ? parseCouponYmd(coupon.couponValidToYmd) ?? ''
          : '';
      const { validAfter, validBefore } = redeemValidityForCoupon(dr, vfStore, vtStore);
      const rDeadline = Math.floor(Date.now() / 1000) + 3600;
      const rNonce = ethers.hexlify(ethers.randomBytes(32));
      const redeemData = encodeCreateRedeemBatchBundle(
        codes,
        0n,
        0,
        validAfter,
        validBefore,
        [BigInt(tokenIdStr)],
        [1n]
      );
      const redeemSig = await signExecuteForOwner(
        p0.privateKeyArmor.trim(),
        cardAddr,
        redeemData,
        rDeadline,
        rNonce
      );
      const redeemRes = await postCardCreateRedeem({
        cardAddress: cardAddr,
        codes,
        points6: '0',
        validAfter,
        validBefore,
        deadline: rDeadline,
        nonce: rNonce,
        ownerSignature: redeemSig,
        tokenIds: [tokenIdStr],
        amounts: ['1'],
        attr: 0,
      });
      if (!redeemRes.success || !redeemRes.codes?.length) {
        setCardIssuanceOwnerAdminNotice({
          kind: 'warn',
          text: redeemRes.error ?? 'Failed to register redeem codes on-chain.',
        });
        return;
      }

      const batch: CardRedeemBatch = {
        batchId: `coupon-${coupon.id}-${Date.now()}`,
        cardAddress: cardAddr,
        points6: '0',
        pointsHuman: '1 NFT',
        createdAt: generatedAt,
        kind: 'issued_nft_coupon',
        issuedNftTokenId: tokenIdStr,
        couponId: coupon.id,
        items: redeemItems,
      };
      const prev = CoNET_Data;
      if (prev) {
        const updatedList: CardRedeemBatch[] = [
          ...(((prev as { cardRedeems?: CardRedeemBatch[] }).cardRedeems ?? []) as CardRedeemBatch[]),
          batch,
        ];
        setCoNET_Data({ ...prev, cardRedeems: updatedList } as typeof prev);
        await storeSystemData();
        setCardIssuanceCouponRedeemsVersion((v) => v + 1);
      }

      setCardIssuanceCoupons((prev) =>
        prev.map((row) => {
          if (row.id !== couponId) return row;
          const leftN = parseCardIssuanceCouponIssueLeftN(row);
          return { ...row, issueLeft: String(Math.max(0, leftN - batchCount)) };
        })
      );
      setCardIssuanceCouponRedeemStatuses((prev) => {
        const next = { ...prev };
        for (const item of redeemItems) {
          next[item.hash] = 'pending';
        }
        return next;
      });
      setCardIssuanceCouponRedeemPageByCouponId((prev) => ({ ...prev, [couponId]: 1 }));
      setCardIssuanceOwnerAdminNotice({
        kind: 'ok',
        text:
          batchCount === 1
            ? '1 redeem code registered on-chain.'
            : `${batchCount.toLocaleString()} redeem codes registered on-chain in one batch (max ${CARD_ISSUANCE_REDEEM_REGISTER_BATCH_MAX.toLocaleString()} per batch).`,
      });
    } catch (e: unknown) {
      setCardIssuanceOwnerAdminNotice({
        kind: 'warn',
        text: e instanceof Error ? e.message : String(e),
      });
    } finally {
      setCardIssuanceCouponRedeemRegisteringId(null);
    }
  },
  [cardIssuanceCoupons, cardIssuanceExistingCard?.cardAddress, profiles, cardIssuanceCouponRedeemBatchQty]
);

