   const yearTopups = overviewYearActivityTxs
     .filter((t) => t.type === 'In-Store Top-Up')
     .reduce((sum, t) => sum + topupTxDisplayRowIssuedAmount(t), 0)
   const cadOracle = oracleCadUsdc ?? ORACLE_CAD_USDC_FALLBACK
